/* A marca sai inteira, numa cor so, com o slogan por baixo em versal fechada de
   .1em. Nao pendura contador grafico como a AW, nao fica sem linha de apoio como
   a AU, nao ganha pincelada de 4px como a AR e nao carrega glifo desenhado como
   a AT. Quem responde pela identidade grafica aqui e a moldura repartida, que e
   o cabecalho inteiro e nao um enfeite ao lado do nome. */
function bbLogo(ctx, cls) {
  const { c, H } = ctx;
  const nome = String(ctx.site.shortName || ctx.site.name).trim();
  const tag = ctx.site.tagline ? `<i>${H.esc(ctx.site.tagline)}</i>` : '';
  return `<a class="${c(cls)}" href="/"><b>${H.esc(nome)}</b>${tag}</a>`;
}

function bbHeader(ctx, menu) {
  const { c, H } = ctx;
  const links = (menu || []).map(x => `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('cinta')}"><div class="${c('encaixe')}">
${bbLogo(ctx, 'firma')}
<nav class="${c('veredas')}" aria-label="Editorias">${links}</nav>
</div></header>
<main class="${c('roda')}">`;
}

function bbFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const eds = (menu || []).map(x => `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `</main>
<footer class="${c('alicerce')}"><div class="${c('alicercein')}">
<div class="${c('pilares')}">
<div>${bbLogo(ctx, 'firma')}<p class="${c('sobrenos')}">${H.esc(site.description || site.tagline || '')}</p></div>
<div><h3>Editorias</h3>${eds}</div>
<div><h3>Institucional</h3>${H.instLinks()}</div>
<div><h3>Redação</h3>
<a href="/contato/">Fale com a redação</a>
<a href="/contato/">Sugerir uma pauta</a>
<a href="/contato/">Corrigir uma informação</a>
<a href="/busca/">Buscar no acervo</a></div>
</div>
<div class="${c('arrimo')}">&copy; ${H.year()} ${H.esc(site.name)}. Todos os direitos reservados. ${H.esc(site.domain)}</div>
</div></footer>
${H.bodyEnd()}`;
}

/* ---------- auxiliares ---------- */

/* A cela larga do elo: foto em 16/9, editoria, titulo grande, resumo e data.
   Sem foto ela nao deixa moldura vazia, so comeca pelo texto. */
function bbViga(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('viga')}" href="${H.url(a)}">`
    + `${a.image ? `<span class="im">${H.pic(a, true)}</span>` : ''}`
    + `<span class="${c('chave')}">${H.cat(a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 200))}</span>` : ''}`
    + `<time datetime="${H.esc(a.date)}">${H.esc(H.dateShort(a.date))}</time></a>`;
}

/* Cada uma das duas chamadas empilhadas na cela estreita do elo. Sem imagem:
   a foto e privilegio da cela larga, e e isso que sustenta a proporcao. */
function bbRamo(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('ramo')}" href="${H.url(a)}">`
    + `<span class="${c('chave')}">${H.cat(a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 120))}</span>` : ''}`
    + `<time datetime="${H.esc(a.date)}">${H.esc(H.dateShort(a.date))}</time></a>`;
}

/* Peca do renque: foto curta, editoria, titulo e data. Quatro delas dividem a
   mesma moldura, e o flex de base zero mantem a fila igual com 1, 2, 3 ou 4. */
function bbPeca(ctx, a) {
  const { c, H } = ctx;
  return `<a class="${c('peca')}" href="${H.url(a)}">`
    + `${a.image ? `<span class="im">${H.pic(a, false)}</span>` : ''}`
    + `<span class="${c('chave')}">${H.cat(a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `<time datetime="${H.esc(a.date)}">${H.esc(H.dateShort(a.date))}</time></a>`;
}

/* Cela da trama de editoria: sem imagem, so texto. O hairline que a separa da
   vizinha e o fundo da trama aparecendo pelo gap de 1px. */
function bbCelula(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('celula')}" href="${H.url(a)}">`
    + `<span class="${c('chave')}">${H.cat(a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 135))}</span>` : ''}`
    + `<time datetime="${H.esc(a.date)}">${H.esc(H.dateShort(a.date))}</time></a>`;
}

/* Linha da listagem: texto a esquerda e miniatura REDONDA a direita, dentro da
   moldura unica. Sem foto, o texto ocupa a linha inteira. */
function bbVerbete(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('verbete')}${a.image ? '' : ` ${c('avulso')}`}" href="${H.url(a)}">`
    + `<span class="tx"><span class="${c('chave')}">${H.cat(a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 165))}</span>` : ''}`
    + `<time datetime="${H.esc(a.date)}">${H.esc(H.dateShort(a.date))}</time></span>`
    + `${a.image ? `<span class="im">${H.pic(a, false)}</span>` : ''}</a>`;
}

/* Titulo de secao centralizado. O link de "ver tudo" nao vive aqui: ele desce
   como faixa conjugada no pe da moldura, escrito pelo bbHome. */
function bbLetreiro(ctx, nome) {
  const { c, H } = ctx;
  return `<h2 class="${c('letreiro')}">${H.esc(nome)}</h2>`;
}

/* ---------- paginas ---------- */

function bbHome(ctx, arts, menu) {
  const { c, H } = ctx;
  const pref = ctx.site.heroFrom;
  const fila = pref ? [...arts.filter(a => a.category && a.category.slug === pref),
                       ...arts.filter(a => !a.category || a.category.slug !== pref)] : arts;

  // tempo 1: o elo, uma moldura so com a chamada larga a esquerda e duas
  // empilhadas a direita. Com uma materia so, a moldura vira cela unica
  const lead = fila[0];
  const lados = fila.slice(1, 3);
  const elo = lead
    ? `<section class="${c('elo')}${lados.length ? '' : ` ${c('unico')}`}">`
      + bbViga(ctx, lead)
      + `${lados.length ? `<div class="${c('apoio')}">${lados.map(a => bbRamo(ctx, a)).join('')}</div>` : ''}`
      + `</section>`
    : '';

  // tempo 2: o renque de quatro pecas encostadas, dividindo fio vertical
  const quatro = fila.slice(3, 7);
  const renque = quatro.length
    ? `<section class="${c('renque')}" aria-label="Em pauta">${quatro.map(a => bbPeca(ctx, a)).join('')}</section>`
    : '';

  const usados = new Set([lead, ...lados, ...quatro].filter(Boolean).map(a => a.slug));
  const rest = fila.slice(1 + lados.length + quatro.length);
  const byCat = new Map();
  const fixas = Array.isArray(ctx.site.homeSections) ? ctx.site.homeSections : null;
  if (fixas) {
    for (const cs of fixas) {
      const itens = arts.filter(a => a.category && a.category.slug === cs && !usados.has(a.slug));
      if (itens.length) byCat.set(cs, { name: itens[0].category.name, items: itens });
    }
  } else {
    for (const a of rest) {
      if (usados.has(a.slug)) continue;
      const cs = a.category ? a.category.slug : 'noticias';
      if (!byCat.has(cs)) byCat.set(cs, { name: a.category ? a.category.name : 'Notícias', items: [] });
      byCat.get(cs).items.push(a);
    }
  }

  // tempo 3: cada editoria numa trama de ate tres celas, com a faixa do "ver
  // tudo" conjugada no pe. O bloco aceita UMA materia: o auto-fit da trama
  // fecha as pistas vazias e a cela sozinha ocupa a moldura inteira
  const vistos = new Set();
  const blocos = [...byCat.entries()]
    .map(([cs, v]) => [cs, v, v.items.filter(a => !vistos.has(a.slug)).slice(0, 3)])
    .filter(([, , q]) => q.length >= 1)
    .slice(0, 8)
    .map(([cs, v, q]) => {
      q.forEach(a => vistos.add(a.slug));
      return `<section class="${c('juncao')}">${bbLetreiro(ctx, v.name)}`
        + `<div class="${c('trama')}">${q.map(a => bbCelula(ctx, a)).join('')}</div>`
        + `<a class="${c('arremate')}" href="${H.curl(cs)}">Tudo em ${H.esc(v.name)}</a></section>`;
    }).join('\n');

  return `${H.head(ctx, H.homeMeta(ctx.site))}
${bbHeader(ctx, menu)}
${H.h1(ctx)}
${elo}
${renque}
${blocos}
${bbFooter(ctx, menu)}`;
}

function bbArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;

  // Todo h2 recebe id, para ancora direta. Esta arquitetura NAO monta sumario,
  // mas ainda assim separa o h2 que pertence ao TEXTO do h2 que vem depois do
  // ultimo paragrafo do corpo: so o primeiro leva o atributo que liga os dois
  // circulos sobrepostos, para que o titulo de qualquer bloco anexado depois do
  // artigo nao seja lido como secao dele. O corte e a posicao do ultimo
  // fechamento de paragrafo.
  const cru = String(art.content);
  const fimTexto = cru.lastIndexOf('</p>');
  let n = 0;
  let corpo = cru.replace(/<h2\b([^>]*)>([\s\S]*?)<\/h2>/gi, (m, attrs, txt, offset) => {
    if (/\bid=/.test(attrs)) return m;
    const rotulo = txt.replace(/<[^>]+>/g, '').trim();
    if (!rotulo) return m;
    n += 1;
    const daTexto = fimTexto < 0 || offset < fimTexto;
    return `<h2 id="parte${n}"${daTexto ? ' data-b="1"' : ''}${attrs}>${txt}</h2>`;
  });

  // conteudo largo rola dentro do proprio conteiner, nunca a pagina inteira
  corpo = corpo
    .replace(/<table\b[\s\S]*?<\/table>/gi, m => `<div class="${c('respiro')}">${m}</div>`)
    .replace(/<pre\b[\s\S]*?<\/pre>/gi, m => `<div class="${c('respiro')}">${m}</div>`);

  // o credito ocupa a cela da direita da parelha, com retrato redondo quando o
  // autor esta na equipe e sem retrato quando nao esta
  const eq = (ctx.site.equipe || []).find(x => x.nome === art.author);
  const credito = eq
    ? `<a class="${c('credito')}" rel="author" href="/autor/${H.esc(eq.slug)}/"><img src="/img/autores/${H.esc(eq.slug)}.webp" width="56" height="56" alt="" loading="lazy"><span><b>${H.esc(eq.nome)}</b><i>${H.esc(P.dstr)} &middot; ${P.readMin} min de leitura</i></span></a>`
    : `<span class="${c('credito')}"><span><b>${H.esc(art.author || ctx.site.name)}</b><i>${H.esc(P.dstr)} &middot; ${P.readMin} min de leitura</i></span></span>`;

  const fig = art.image
    ? `<figure class="${c('retrato')}">${H.pic(art, true)}${art.image.caption ? `<figcaption>${H.esc(art.image.caption)}</figcaption>` : ''}</figure>`
    : '';

  // a leitura relacionada reaproveita o renque: as tres materias ficam
  // encostadas na mesma moldura, como tudo nesta arquitetura
  const rel = (related && related.length)
    ? `<section class="${c('elenco')}">${bbLetreiro(ctx, 'Leia também')}`
      + `<div class="${c('renque')}">${related.slice(0, 3).map(a => bbPeca(ctx, a)).join('')}</div></section>`
    : '';

  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${bbHeader(ctx, menu)}
<article class="${c('tribuna')}">
${H.crumbs(ctx, art, P)}
<div class="${c('parelha')}">
<div class="${c('dito')}">
<span class="${c('chave')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<span class="${c('chamada')}">${H.esc(art.dek)}</span>` : ''}
</div>
${credito}
</div>
${fig}
<div class="${c('prosa')}">${corpo}</div>
</article>
${rel}
${bbFooter(ctx, menu)}`;
}

function bbList(ctx, opts) {
  const { c, H } = ctx;
  return `${H.head(ctx, H.listMeta(ctx, opts))}
${bbHeader(ctx, opts.menu)}
${bbLetreiro(ctx, opts.title)}
<div class="${c('fileira')}">${opts.items.map(a => bbVerbete(ctx, a)).join('')}</div>
${bbFooter(ctx, opts.menu)}`;
}


/* ===================== ARCH BA =====================
   Portal: noticiasagoras.com  ("Notícias Agoras", curto "Agoras")
   Conceito: PLANTAO. O nome do portal e um adverbio de tempo no plural, entao a
   arquitetura assume o agora como assunto: TODA chamada carrega MARCACAO DE
   HORARIO, no formato 14h32, e nao apenas a data. A pagina e densa, apertada e
   de hierarquia dura, o oposto de um site contemplativo. O motivo grafico unico
   e a SOMBRA DURA DESLOCADA de 4px por 4px sem desfoque nenhum, que e o registro
   fora de esquadro de uma pagina impressa, e o segundo motivo e o FIO GROSSO de
   6px que abre cada bloco como fecho de caderno de jornal. A Bevan e uma slab de
   peso unico e muito escuro: a manchete sai grande, com entrelinha de 1.02, e
   nunca precisa de negrito porque nao existe negrito nela.

   A chave tem DUAS letras: as 26 letras simples acabaram e a serie segue em AA
   ate BA. O deploy precisa casar a marca `ARCH BA` inteira, nunca so `ARCH B`.

   ATENCAO DE FONTE: a Bevan tem UM peso so, o 400. Todo uso de var(--fd) neste
   arquivo esta em font-weight:400 de proposito. Pedir 700 faz o navegador
   engordar o desenho por sintese e o resultado fica borrado.

   ACERVO: cerca de 96 artigos em 5 editorias. Nenhum bloco desta arquitetura
   exige minimo alto: a abertura aceita 1 artigo e cada editoria entra com UMA
   materia se for so o que houver (`q.length >= 1`). As colunas da abertura somem
   sozinhas quando nao ha material para elas, e a grade da abertura troca de
   proporcao por classe, sem deixar buraco.

   Divergente das irmas lidas (AV, AX, X, AN) em todas as camadas:

   - CABECALHO em dois andares onde o SEGUNDO ANDAR E FEITO DE CAIXAS: cada
     editoria e um retangulo de canto reto com contorno de 2px e a SOMBRA DURA
     de 4px por 4px, e no hover a caixa desliza para dentro da propria sombra.
     No primeiro andar a marca e o slogan ficam LADO A LADO, separados por uma
     REGUA VERTICAL DE 4px na cor do acento, e nao empilhados. A AV poe a marca a
     esquerda e um algarismo vazado gigante a direita, com as editorias em linha
     crua embaixo; a AX faz a marca atravessar uma margem vertical e recua as
     editorias ate a coluna de texto; a X mantem a marca sozinha em cima e joga
     as editorias numa barra de fundo cheio com divisores verticais; a AN cola
     uma tarja inclinada de 3 graus na marca e poe traco curto sob cada editoria.
     Nenhuma delas transforma o item de navegacao em caixa, nenhuma poe o slogan
     na horizontal ao lado do nome e nenhuma usa sombra em lugar nenhum do
     cabecalho;

   - HOME em TRES COLUNAS de proporcao 1.6 por 1 por 0.85, que e a abertura
     inteira num golpe so. Na coluna larga a manchete traz kicker, horario,
     titulo grande e resumo, e SO ENTAO a foto, que fica ABAIXO do texto e nao
     acima dele. Na coluna do meio tres chamadas curtas sem foto, separadas por
     fio fino. Na coluna estreita o MINUTO A MINUTO: uma caixa de contorno de 2px
     com a sombra dura, onde cada linha e horario mais titulo, sem foto e sem
     resumo. Depois disso as editorias vem em GRADE DE QUATRO COLUNAS. A AV abre
     em duas colunas desiguais com nove titulos e fecha em grade de tres; a AX
     resolve a home inteira em coluna unica de entradas; a X abre com manchete
     deitada 5/7, faixa de quatro e fecha editoria em duas colunas desiguais; a
     AN abre com oito posicoes numeradas em coluna unica e fecha em grade de
     tres. Nenhuma delas reparte a abertura em TRES colunas, nenhuma poe a foto
     da manchete depois do texto e nenhuma fecha editoria em QUATRO colunas;

   - ARTIGO em coluna unica de 64ch, sem trilho e sem sumario. O elemento
     decorativo do h2 nao e glifo, nao e numeral e nao e barra: e a PROPRIA
     SOMBRA DURA APLICADA AO TEXTO do titulo, um text-shadow de 3px por 3px sem
     desfoque num vermelho claro, que le como impressao fora de registro. A AV
     poe numeral de secao em contorno vazado a esquerda do h2; a AX desenha um
     asterisco de tres bandas de gradiente pousado na margem; a X deixa o h2 cru
     e resolve o destaque numa capitular; a AN poe o numero da secao dentro de um
     circulo cheio. Nenhuma das quatro toca no desenho das letras do proprio h2;

   - LISTAGEM em linha de TRES CAMPOS com a MINIATURA NO MEIO: a coluna da
     esquerda leva o horario em cima e a data embaixo, a do meio leva a foto em
     3/2 com a sombra dura, e a da direita leva kicker, titulo e resumo. A AV poe
     numeral vazado a esquerda e miniatura a direita; a AX nao poe miniatura
     nenhuma, exceto na primeira linha; a X poe miniatura a esquerda em 190px; a
     AN poe miniatura a direita em 150px. Miniatura NO MEIO, entre a hora e o
     texto, nao existe em nenhuma delas;

   - BEVAN no display com READEX PRO no corpo: slab de peso unico, muito escura e
     de haste reta, que e o corpo de manchete de plantao, sobre uma grotesca
     arredondada de leitura com numeral tabular. Nenhuma irma usa qualquer uma
     das duas (AV: Domine + Hanken Grotesk, AX: Spectral + Hind, X: Chivo +
     Spectral, AN: Roboto Slab + Public Sans). A AN tambem e slab no display, mas
     a Roboto Slab tem cinco pesos e vive de 700 e 800; a Bevan tem um peso so, e
     por isso a hierarquia daqui e feita por TAMANHO, nunca por peso;

   - VERMELHO DE URGENCIA #b91c1c sobre tinta #1c1210, que e um marrom quase
     preto, e papel #fffcfa, que e um branco levemente quente. A AV e verde agua
     em contorno, a AX e ouro escuro com uma margem rosa, a X e violeta com
     ambar, a AN e carmim. O carmim da AN e a cor mais proxima, mas ela vive em
     area cheia, em circulo e em tarja; aqui o vermelho quase nunca preenche:
     ele vive na SOMBRA que cai fora da caixa, que e o oposto de preenchimento;

   - CANTO DE 0px e SOMBRA DURA DESLOCADA de 4px por 4px sem desfoque, mais FIO
     GROSSO de 6px abrindo bloco. A AV tem canto de 6px com sombra difusa leve, a
     AX tem canto reto e zero sombra, a X tem canto de 8px com sombra difusa
     grande no hover, a AN tem canto de 2px com sombra difusa de 1px. Nenhuma
     delas usa sombra sem desfoque, que e justamente o que separa o impresso do
     digital.

   Esta arquitetura NAO monta sumario a partir dos h2. Ainda assim ela respeita a
   regra do h2 posterior ao ultimo paragrafo: a sombra dura do titulo so e ligada
   nos h2 que ficam ANTES do ultimo fechamento de paragrafo do corpo, para que o
   titulo de qualquer bloco anexado depois do texto nao seja lido como secao. O
   corte e feito pela posicao do ultimo `</p>`.

   O bloco de compartilhar NAO e desenhado aqui: o motor ja injeta o dele. Este
   arquivo apenas o veste por s('share'), para que ele receba o fio grosso e a
   sombra dura da casa.

   Nada centralizado alem da marca, conforme a regra do Anderson: paragrafo,
   lista, chamada, cartao e FAQ sempre a esquerda. No mobile a pagina quebra em
   760px e em 520px, a abertura de tres colunas vira coluna unica, a miniatura da
   listagem sai do meio e vai para a frente da linha e depois some. Tabela e
   bloco de codigo rolam dentro do proprio conteiner, e o corpo da pagina nunca
   rola na horizontal. Nenhuma string deste arquivo usa travessao.

   Fontes: o arch le var(--fd) e var(--fb), quem carrega e o theme do
   sites.json. Provisionar assim:
     fontDisplay: '"Bevan", Georgia, serif'
     fontBody:    '"Readex Pro", Segoe UI, sans-serif'
     googleUrl:   https://fonts.googleapis.com/css2
                  ?family=Bevan
                  &family=Readex+Pro:wght@300;400;500;600;700&display=swap
   Paleta do theme: paper #fffcfa, ink #1c1210, primary #b91c1c.
   Tokens do theme: container 1280px, baseFs 16.5px, kickerLs .05em, radius 0.
   ================================================== */

function baCss(ctx) {
  const { s } = ctx;
  return `
:root{
--bar:0px;
--baac:#b91c1c;--baac-dk:#8f1414;--baac-lt:#fca5a5;
--baink:#1c1210;--bapaper:#fffcfa;
--bapale:color-mix(in srgb,var(--baac) 9%,var(--bapaper));
--baecho:color-mix(in srgb,var(--baac) 26%,var(--bapaper));
--bafio:color-mix(in srgb,var(--baink) 22%,transparent);
--bafio2:color-mix(in srgb,var(--baink) 11%,transparent);
--bafraco:color-mix(in srgb,var(--baink) 52%,transparent);
/* a assinatura da casa: deslocamento de 4px por 4px e desfoque ZERO. Nao existe
   sombra difusa em lugar nenhum desta arquitetura */
--badura:4px 4px 0 var(--baink);
--baduraac:4px 4px 0 var(--baac);
--badurinha:3px 3px 0 var(--baink)
}
body{background:var(--bapaper);color:var(--baink);font-size:16.5px}
${s('banca')}{max-width:var(--maxw);margin:0 auto;padding:0 26px;box-sizing:border-box;width:100%}
${s('banca')} > *{max-width:100%;box-sizing:border-box}

/* ---------- cabecalho: marca e slogan lado a lado, editorias em caixa ---------- */
${s('frontao')}{background:var(--bapaper);border-bottom:6px solid var(--baink)}
${s('frontin')}{max-width:var(--maxw);margin:0 auto;padding:20px 26px 18px;box-sizing:border-box}
${s('cume')}{display:flex;align-items:center;gap:0 20px;flex-wrap:wrap}
${s('emblema')}{display:inline-block;text-decoration:none;color:inherit;flex:none;line-height:1}
${s('emblema')} b{display:block;font-family:var(--fd);font-weight:400;font-size:36px;line-height:.94;letter-spacing:-.028em;color:var(--baink)}
${s('emblema')}:hover b{color:var(--baac)}
/* o slogan nao desce para debaixo do nome: fica na mesma linha, encostado numa
   regua vertical de 4px no vermelho */
${s('slogan')}{display:block;flex:none;font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--bafraco);border-left:4px solid var(--baac);padding-left:16px;line-height:1.32;max-width:22ch;text-align:left}
/* segundo andar: cada editoria e uma caixa de contorno de 2px com a sombra dura.
   No hover a caixa anda 4px para a direita e para baixo e entra na propria
   sombra, que e o gesto de um carimbo sendo pressionado */
${s('pauta')}{display:flex;align-items:stretch;flex-wrap:wrap;gap:14px 14px;margin:22px 0 4px}
${s('pauta')} a{display:inline-block;font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.05em;color:var(--baink);text-decoration:none;background:var(--bapaper);border:2px solid var(--baink);border-radius:var(--bar);padding:9px 15px;line-height:1.15;box-shadow:var(--badura);transition:transform .14s ease,box-shadow .14s ease,background .14s ease,color .14s ease}
${s('pauta')} a:hover{transform:translate(4px,4px);box-shadow:0 0 0 var(--baac);background:var(--baac);color:#fff;border-color:var(--baac)}

/* ---------- atomos ---------- */
${s('etiqueta')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.05em;color:var(--baac)}
${s('etiqueta')} a{color:inherit;text-decoration:none}
${s('etiqueta')} a:hover{color:var(--baac-dk);text-decoration:underline;text-underline-offset:3px}
${s('legenda')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.05em;color:var(--bafraco);margin-bottom:12px}
/* a marcacao de horario, que e o motivo do portal: ela acompanha toda chamada */
${s('hora')}{display:inline-block;font-family:var(--fb);font-size:11.5px;font-weight:700;letter-spacing:.02em;color:var(--baac);font-variant-numeric:tabular-nums}
${s('hora')} u{text-decoration:none;color:var(--bafraco);font-weight:500;margin-left:9px}
/* cabecalho de secao: o fio grosso de 6px abre o bloco, e o titulo pousa nele */
${s('testeira')}{display:flex;align-items:baseline;justify-content:space-between;gap:8px 22px;flex-wrap:wrap;margin:0 0 22px;padding-top:14px;border-top:6px solid var(--baink)}
${s('testeira')} h2{font-family:var(--fd);font-weight:400;font-size:clamp(19px,2vw,25px);line-height:1.1;letter-spacing:-.02em;color:var(--baink);margin:0;flex:none;text-align:left}
${s('testeira')} .more{font-family:var(--fb);font-size:11.5px;font-weight:700;letter-spacing:.05em;color:var(--baac);text-decoration:none;flex:none}
${s('testeira')} .more:hover{color:var(--baac-dk);text-decoration:underline;text-underline-offset:4px}
${s('lance')}{margin:0 0 50px}

/* ---------- home: abertura em tres colunas ---------- */
/* 1.6 por 1 por 0.85. Quando falta material a grade troca de proporcao pelas
   classes de falta, e nunca sobra coluna vazia */
${s('plantao')}{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr) minmax(0,.85fr);gap:0 34px;align-items:start;margin:26px 0 46px}
${s('plantao')}${s('sem2')}{grid-template-columns:minmax(0,1.6fr) minmax(0,.9fr)}
${s('plantao')}${s('sem3')}{grid-template-columns:minmax(0,1.6fr) minmax(0,1fr)}
${s('plantao')}${s('sem2')}${s('sem3')}{grid-template-columns:minmax(0,1fr)}

/* a manchete: kicker, horario, titulo grande, resumo e SO DEPOIS a foto */
${s('manchetao')}{display:block;text-decoration:none;color:inherit;min-width:0}
${s('manchetao')} .k{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap;margin-bottom:11px}
${s('manchetao')} .h{display:block;font-family:var(--fd);font-weight:400;font-size:clamp(30px,3.6vw,46px);line-height:1.02;letter-spacing:-.03em;color:var(--baink);text-align:left}
${s('manchetao')}:hover .h{color:var(--baac)}
${s('manchetao')} .d{display:block;font-family:var(--fb);font-size:16px;font-weight:400;line-height:1.66;color:var(--bafraco);margin-top:14px;max-width:56ch;text-align:left}
${s('manchetao')} .im{display:block;width:100%;aspect-ratio:16/9;overflow:hidden;background:var(--bafio2);border:2px solid var(--baink);border-radius:var(--bar);box-shadow:var(--baduraac);margin:24px 4px 6px 0;box-sizing:border-box}
${s('manchetao')} .im img{width:100%;height:100%;object-fit:cover;display:block}

/* coluna do meio: tres chamadas curtas, sem foto, separadas por fio fino */
${s('curso')}{display:flex;flex-direction:column;min-width:0;border-left:1px solid var(--bafio2);padding-left:34px}
${s('flash')}{display:block;text-decoration:none;color:inherit;padding:15px 0;border-bottom:1px solid var(--bafio2)}
${s('flash')}:first-child{padding-top:0}
${s('flash')}:last-child{border-bottom:0}
${s('flash')} .k{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;margin-bottom:9px}
${s('flash')} .h{display:block;font-family:var(--fd);font-weight:400;font-size:19px;line-height:1.16;letter-spacing:-.018em;color:var(--baink);text-align:left}
${s('flash')}:hover .h{color:var(--baac)}
${s('flash')} .d{display:block;font-family:var(--fb);font-size:14px;font-weight:400;line-height:1.62;color:var(--bafraco);margin-top:9px;text-align:left}

/* coluna estreita: o minuto a minuto, dentro da caixa de sombra dura */
${s('minuto')}{border:2px solid var(--baink);border-radius:var(--bar);box-shadow:var(--badura);padding:16px 18px 6px;box-sizing:border-box;min-width:0;margin-right:4px;background:var(--bapale)}
${s('minuto')} > b{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.05em;color:var(--baac);padding-bottom:11px;border-bottom:2px solid var(--baink);margin-bottom:4px}
${s('pulso')}{display:block;text-decoration:none;color:inherit;padding:12px 0;border-bottom:1px solid var(--bafio2)}
${s('pulso')}:last-child{border-bottom:0}
${s('pulso')} .h{display:block;font-family:var(--fb);font-size:14px;font-weight:500;line-height:1.44;color:var(--baink);margin-top:7px;text-align:left}
${s('pulso')}:hover .h{color:var(--baac)}

/* ---------- home: editorias em grade de quatro ---------- */
${s('quadra')}{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:30px 26px;align-items:start}
${s('verbete')}{display:block;text-decoration:none;color:inherit;min-width:0}
${s('verbete')} .im{display:block;width:100%;aspect-ratio:3/2;overflow:hidden;background:var(--bafio2);border:2px solid var(--baink);border-radius:var(--bar);box-shadow:var(--badurinha);margin:0 3px 16px 0;box-sizing:border-box;transition:box-shadow .14s ease}
${s('verbete')}:hover .im{box-shadow:3px 3px 0 var(--baac)}
${s('verbete')} .im img{width:100%;height:100%;object-fit:cover;display:block}
${s('verbete')} .h{display:block;font-family:var(--fd);font-weight:400;font-size:17.5px;line-height:1.16;letter-spacing:-.018em;color:var(--baink);margin-top:9px;text-align:left}
${s('verbete')}:hover .h{color:var(--baac)}
${s('verbete')} .d{display:block;font-family:var(--fb);font-size:13.5px;font-weight:400;line-height:1.62;color:var(--bafraco);margin-top:9px;text-align:left}
${s('verbete')} .k{display:block;margin-top:11px}

/* ---------- listagem: hora, miniatura NO MEIO, texto ---------- */
${s('arquivo')}{display:block;margin:2px 0 48px;border-top:6px solid var(--baink)}
${s('talao')}{display:grid;grid-template-columns:88px 184px minmax(0,1fr);gap:0 24px;align-items:start;text-decoration:none;color:inherit;padding:22px 0;border-bottom:1px solid var(--bafio2)}
${s('talao')} .k{display:block;text-align:left;padding-top:3px}
${s('talao')} .k b{display:block;font-family:var(--fd);font-weight:400;font-size:22px;line-height:1;letter-spacing:-.02em;color:var(--baac);font-variant-numeric:tabular-nums}
${s('talao')} .k i{display:block;font-style:normal;font-family:var(--fb);font-size:11px;font-weight:600;letter-spacing:.05em;color:var(--bafraco);margin-top:8px;font-variant-numeric:tabular-nums}
${s('talao')} .im{display:block;width:100%;aspect-ratio:3/2;overflow:hidden;background:var(--bafio2);border:2px solid var(--baink);border-radius:var(--bar);box-shadow:var(--badurinha);box-sizing:border-box;margin:0 3px 3px 0}
${s('talao')}:hover .im{box-shadow:3px 3px 0 var(--baac)}
${s('talao')} .im img{width:100%;height:100%;object-fit:cover;display:block}
${s('talao')} .tx{display:block;min-width:0;text-align:left}
${s('talao')} .h{display:block;font-family:var(--fd);font-weight:400;font-size:21px;line-height:1.14;letter-spacing:-.022em;color:var(--baink);margin-top:9px;text-align:left}
${s('talao')}:hover .h{color:var(--baac)}
${s('talao')} .d{display:block;font-family:var(--fb);font-size:14.5px;font-weight:400;line-height:1.66;color:var(--bafraco);margin-top:10px;max-width:64ch;text-align:left}

/* ---------- artigo: coluna unica de 64ch, sem trilho ---------- */
${s('impresso')}{max-width:880px;margin:0 auto;padding:26px 26px 12px;box-sizing:border-box}
${s('cabeco')}{margin:0 0 22px}
${s('cabeco')} h1{font-family:var(--fd);font-weight:400;font-size:clamp(30px,3.9vw,48px);line-height:1.02;letter-spacing:-.032em;color:var(--baink);margin:12px 0 16px;max-width:20ch;text-align:left}
${s('sutia')}{display:block;font-family:var(--fb);font-size:18px;font-weight:400;line-height:1.64;color:var(--bafraco);margin:0 0 22px;max-width:58ch;text-align:left}
/* a assinatura: o retrato quadrado ganha contorno de 2px e a sombra dura menor */
${s('assina')}{display:inline-flex;align-items:center;gap:14px;text-decoration:none;color:inherit}
${s('assina')} img{display:block;flex:none;width:46px;height:46px;object-fit:cover;background:var(--ph);border:2px solid var(--baink);border-radius:var(--bar);box-shadow:var(--badurinha);margin:0 3px 3px 0}
${s('assina')}:hover img{box-shadow:3px 3px 0 var(--baac)}
${s('assina')} b{display:block;font-family:var(--fb);font-size:14.5px;font-weight:600;color:var(--baink)}
${s('assina')}:hover b{color:var(--baac)}
${s('assina')} i{display:block;font-style:normal;font-family:var(--fb);font-size:12.5px;font-weight:400;color:var(--bafraco);margin-top:5px;font-variant-numeric:tabular-nums}
/* o fio grosso que fecha a abertura do texto, o mesmo do topo de cada bloco */
${s('fiogrosso')}{display:block;height:6px;background:var(--baink);margin:26px 0 0;max-width:64ch}
${s('cliche')}{margin:26px 0 0;max-width:64ch}
${s('cliche')} img{width:100%;display:block;border:2px solid var(--baink);border-radius:var(--bar);box-shadow:var(--baduraac);box-sizing:border-box}
${s('cliche')} figcaption{font-family:var(--fb);font-size:12.5px;font-weight:400;line-height:1.62;color:var(--bafraco);padding:16px 0 0;text-align:left}

${s('materia')}{font-family:var(--fb);font-size:17px;font-weight:400;line-height:1.78;color:var(--baink);max-width:64ch;margin-top:26px}
${s('materia')} p{margin:0 0 1.24em;text-align:left}
/* o elemento decorativo do h2 e a SOMBRA DURA aplicada as proprias letras: um
   text-shadow de 3px por 3px sem desfoque, no vermelho claro. Nao ha glifo, nao
   ha numeral, nao ha barra e nao ha recuo. So o h2 anterior ao ultimo fechamento
   de paragrafo recebe o atributo que liga o efeito, para que titulo de bloco
   anexado depois do corpo nao seja lido como secao */
${s('materia')} h2{font-family:var(--fd);font-weight:400;font-size:27px;line-height:1.1;letter-spacing:-.026em;color:var(--baink);margin:1.9em 0 .6em;scroll-margin-top:22px;text-align:left}
${s('materia')} h2[data-e]{text-shadow:3px 3px 0 var(--baecho)}
${s('materia')} h3{font-family:var(--fd);font-weight:400;font-size:20px;line-height:1.2;letter-spacing:-.018em;color:var(--baac-dk);margin:1.7em 0 .5em;scroll-margin-top:22px;text-align:left}
${s('materia')} a{color:var(--baac-dk);text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px}
${s('materia')} a:hover{color:var(--baink)}
${s('materia')} ul,${s('materia')} ol{margin:0 0 1.28em;padding-left:1.4em;text-align:left}
${s('materia')} li{margin-bottom:.55em}
${s('materia')} img{max-width:100%;height:auto;display:block;margin:1.7em 3px 1.7em 0;border:2px solid var(--baink);border-radius:var(--bar);box-shadow:var(--badurinha);box-sizing:border-box}
/* a citacao nao ganha caixa, nao ganha fundo e nao ganha fio lateral: ganha o
   FIO GROSSO em cima e embaixo, que e o fecho de pagina impressa da casa */
${s('materia')} blockquote{margin:1.9em 0;padding:20px 0;border-top:6px solid var(--baac);border-bottom:6px solid var(--baac);font-family:var(--fb);font-size:18.5px;font-weight:500;line-height:1.54;color:var(--baink);text-align:left}
${s('materia')} blockquote p{margin:0;font-family:inherit;font-size:inherit;font-weight:inherit;line-height:inherit;text-align:left}
${s('materia')} blockquote p + p{margin-top:.55em}
${s('materia')} table{width:100%;border-collapse:collapse;margin:0;font-family:var(--fb);font-size:14.5px;min-width:460px}

/* tabela vira cartao no celular: sem isto ela sai da tela e o gesto de
   arrastar nao e descoberto. thead sai da tela mas continua no DOM */
@media(max-width:640px){
  ${s('materia')} .tabwrap{overflow:visible;border:0;background:transparent}
  ${s('materia')} table{min-width:0;display:block;width:auto;overflow:visible}
  ${s('materia')} table caption{display:none}
  ${s('materia')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('materia')} table tbody,${s('materia')} table tr,
  ${s('materia')} table th,${s('materia')} table td{display:block;width:auto}
  ${s('materia')} table tbody tr{background:rgba(255,255,255,.6);border:1px solid rgba(0,0,0,.12);
    border-radius:12px;padding:2px 16px 14px;margin-bottom:12px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('materia')} table tbody th,${s('materia')} table tbody td{border:0;background:transparent;padding:0}
  ${s('materia')} table tbody th{border-bottom:1px solid rgba(0,0,0,.12);padding:13px 0 11px;
    font-weight:700;text-align:left}
  ${s('materia')} table tbody td{padding:12px 0 0;text-align:left;line-height:1.5}
  ${s('materia')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;opacity:.62;margin-bottom:2px}
}
${s('materia')} th,${s('materia')} td{padding:11px 14px;border:1px solid var(--bafio);text-align:left}
${s('materia')} th{background:var(--bapale);font-weight:600;letter-spacing:.02em}
${s('materia')} pre{margin:0;padding:17px 20px;background:var(--bapale);border:2px solid var(--bafio);border-radius:var(--bar);font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:14px;line-height:1.66}
${s('materia')} code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.88em;background:var(--bapale);padding:2px 6px;border-radius:var(--bar)}
${s('materia')} pre code{background:none;padding:0;border:0}
${s('materia')} .nota{font-family:var(--fb);font-size:15px;font-weight:400;line-height:1.7;color:var(--bafraco);background:var(--bapale);border-left:6px solid var(--baac);border-radius:var(--bar);padding:16px 20px;margin:1.7em 0;text-align:left}
/* tabela e bloco de codigo rolam dentro do proprio conteiner: a pagina nunca
   rola na horizontal. O motor entrega os dois crus, entao o baArticle embrulha
   cada um nesta caixa antes de renderizar. */
${s('transborda')}{display:block;overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%;margin:1.7em 0}

/* O bloco de compartilhar e injetado pelo motor. Aqui ele so e VESTIDO: recebe o
   fio grosso por cima e o botao vira caixa de canto reto com a sombra dura */
${s('share')}{margin:40px 0 0;padding-top:22px;border-top:6px solid var(--baink);display:flex;align-items:center;flex-wrap:wrap;gap:12px;max-width:64ch}
${s('share')} .lb{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.05em;color:var(--bafraco);margin-right:6px}
${s('share')} .bt{font-family:var(--fb);font-size:12px;font-weight:600;letter-spacing:.03em;color:var(--baink);background:var(--bapaper);border:2px solid var(--baink);border-radius:var(--bar);padding:9px 15px;line-height:1.15;box-shadow:var(--badurinha);cursor:pointer;transition:transform .14s ease,box-shadow .14s ease,background .14s ease,color .14s ease}
${s('share')} .bt:hover{transform:translate(3px,3px);box-shadow:0 0 0 var(--baac);background:var(--baac);color:#fff;border-color:var(--baac)}

${s('emseguida')}{max-width:var(--maxw);margin:52px auto 0;padding:0 26px;box-sizing:border-box}
${s('emseguidag')}{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;align-items:start}

/* Estas classes vem do HTML das paginas extras (equipe, autor), e o motor as
   renomeia com _clsMapa. O CSS precisa do seletor LITERAL aqui: chamar o
   helper s() nestas classes gera outro nome, porque o s() passa por
   classToken, que e outra funcao de hash.
   (E este comentario nao pode conter cifrao seguido de chave: ele vive dentro
   de um template literal e seria interpolado, quebrando o arquivo.) */
/* ---------- paginas de equipe e de autor ---------- */
.eq-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px 30px;margin:28px 0 12px}
.eq-card{display:grid;grid-template-columns:96px minmax(0,1fr);gap:0 22px;align-items:start;text-decoration:none;color:inherit}
.eq-card img{width:96px;height:96px;display:block;background:var(--ph);object-fit:cover;border:2px solid var(--baink);border-radius:0;box-shadow:3px 3px 0 var(--baink);margin:0 3px 3px 0}
.eq-card:hover img{box-shadow:3px 3px 0 var(--baac)}
.eq-card b,.eq-card h3{display:block;font-family:var(--fd);font-weight:400;font-size:18px;line-height:1.14;letter-spacing:-.02em;color:var(--baink);margin-bottom:8px}
.eq-card:hover b,.eq-card:hover h3{color:var(--baac)}
.eq-area{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.05em;color:var(--baac);margin:0 0 8px}
.eq-res{display:block;font-family:var(--fb);font-size:14px;font-weight:400;line-height:1.7;color:var(--bafraco);margin:0;text-align:left}
.pf-topo{display:flex;gap:26px;align-items:center;margin:0 0 30px;padding:0 0 24px;border-bottom:6px solid var(--baink)}
.pf-topo img{width:108px;height:108px;object-fit:cover;flex:none;background:var(--ph);border:2px solid var(--baink);border-radius:0;box-shadow:4px 4px 0 var(--baac);margin:0 4px 4px 0}
.pf-ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.05em;color:var(--baac);margin:0 0 8px}
.pf-lead{font-family:var(--fd);font-weight:400;font-size:20px;line-height:1.16;letter-spacing:-.02em;color:var(--baink);margin:0;text-align:left}
.pf-obs{font-family:var(--fb);font-size:14px;font-weight:400;line-height:1.72;color:var(--bafraco);background:var(--bapale);border-left:6px solid var(--baac);padding:16px 20px;margin:30px 0 0;text-align:left}
@media(max-width:760px){
.eq-grid{grid-template-columns:1fr;gap:22px}
.eq-card{grid-template-columns:72px minmax(0,1fr);gap:0 16px}
.eq-card img{width:72px;height:72px}
.pf-topo{flex-direction:column;align-items:flex-start;gap:18px}
}

/* ---------- rodape ---------- */
${s('pedestal')}{background:var(--footer-bg);color:var(--footer-tx);margin-top:64px;border-top:6px solid var(--baac)}
${s('pedestin')}{max-width:var(--maxw);margin:0 auto;padding:46px 26px 26px;box-sizing:border-box}
${s('pgrade')}{display:grid;grid-template-columns:1.7fr 1fr 1fr 1fr;gap:34px;margin-bottom:32px}
${s('pgrade')} h3{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.05em;color:#fff;margin-bottom:14px}
${s('pgrade')} a{display:block;font-family:var(--fb);font-size:14px;font-weight:400;color:var(--footer-tx);text-decoration:none;padding:5px 0}
${s('pgrade')} a:hover{color:var(--baac-lt)}
${s('pedestal')} ${s('emblema')} b{color:#fff}
${s('pedestal')} ${s('emblema')}:hover b{color:var(--baac-lt)}
${s('psobre')}{font-family:var(--fb);font-size:14px;font-weight:400;line-height:1.72;color:var(--footer-tx);margin-top:16px;max-width:42ch;text-align:left}
${s('pcarimbo')}{border-top:1px solid color-mix(in srgb,var(--footer-tx) 22%,transparent);padding-top:20px;font-family:var(--fb);font-size:12.5px;font-weight:400;line-height:1.74;color:var(--footer-tx);text-align:left}

@media(max-width:1080px){
/* a coluna do minuto a minuto desce para debaixo da abertura e vira faixa */
${s('plantao')}{grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:0 28px}
${s('plantao')}${s('sem2')}{grid-template-columns:minmax(0,1fr)}
${s('plantao')}${s('sem3')}{grid-template-columns:minmax(0,1.5fr) minmax(0,1fr)}
${s('minuto')}{grid-column:1 / -1;margin-top:30px;margin-right:0}
${s('curso')}{padding-left:28px}
${s('quadra')}{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px 24px}
${s('emseguidag')}{grid-template-columns:repeat(2,minmax(0,1fr))}
${s('talao')}{grid-template-columns:76px 158px minmax(0,1fr);gap:0 20px}
${s('pgrade')}{grid-template-columns:1fr 1fr;gap:30px}
}
@media(max-width:760px){
/* a abertura vira coluna unica e o fio vertical do meio some */
${s('plantao')},${s('plantao')}${s('sem2')},${s('plantao')}${s('sem3')}{grid-template-columns:minmax(0,1fr);gap:0;margin:20px 0 36px}
${s('curso')}{border-left:0;padding-left:0;border-top:1px solid var(--bafio2);margin-top:26px;padding-top:8px}
${s('minuto')}{margin-top:26px}
${s('manchetao')} .h{font-size:30px}
${s('manchetao')} .im{aspect-ratio:3/2;margin-top:20px}
${s('flash')} .h{font-size:19px}
${s('flash')} .d{display:none}
${s('quadra')}{grid-template-columns:repeat(2,minmax(0,1fr));gap:26px 20px}
${s('verbete')} .h{font-size:17px}
${s('verbete')} .d{display:none}
${s('emseguidag')}{grid-template-columns:minmax(0,1fr);gap:26px}
${s('lance')}{margin-bottom:42px}
/* a miniatura sai do meio e vai para a FRENTE da linha; a hora sobe para o texto */
${s('talao')}{grid-template-columns:136px minmax(0,1fr);gap:0 18px}
${s('talao')} .k{display:none}
${s('talao')} .h{font-size:18px}
${s('talao')} .d{display:none}
${s('cabeco')} h1{max-width:none}
${s('materia')}{font-size:16.5px}
${s('materia')} h2{font-size:23px;text-shadow:2px 2px 0 var(--baecho)}
${s('materia')} h2[data-e]{text-shadow:2px 2px 0 var(--baecho)}
${s('materia')} h3{font-size:18.5px}
${s('materia')} blockquote{font-size:17.5px;padding:17px 0}
${s('pgrade')}{grid-template-columns:1fr 1fr;gap:26px}
}
@media(max-width:520px){
${s('banca')}{padding:0 16px}
${s('frontin')}{padding:16px 16px 14px}
${s('impresso')}{padding:22px 16px 12px}
${s('emseguida')}{padding:0 16px}
${s('pedestin')}{padding:36px 16px 22px}
${s('emblema')} b{font-size:28px}
${s('cume')}{gap:12px 16px}
${s('slogan')}{font-size:10.5px;padding-left:13px;max-width:100%}
${s('pauta')}{gap:12px 10px;margin-top:18px}
${s('pauta')} a{font-size:11.5px;padding:8px 12px;box-shadow:var(--badurinha)}
${s('manchetao')} .h{font-size:27px}
${s('quadra')}{grid-template-columns:minmax(0,1fr);gap:28px}
${s('verbete')} .d{display:block}
/* sem espaco para miniatura ao lado de titulo grande, a foto sai da linha */
${s('talao')}{grid-template-columns:minmax(0,1fr);gap:0}
${s('talao')} .im{display:none}
${s('minuto')}{padding:14px 15px 4px}
${s('share')} .bt{padding:10px 14px}
${s('pgrade')}{grid-template-columns:1fr;gap:24px}
}
/* item de grid nasce com min-width:auto e nao encolhe abaixo do conteudo */
${s('plantao')} > *,${s('quadra')} > *,${s('talao')} > *,${s('emseguidag')} > *,${s('pgrade')} > *{min-width:0}
${s('manchetao')} .h,${s('flash')} .h,${s('pulso')} .h,${s('verbete')} .h,${s('talao')} .h,${s('cabeco')} h1{overflow-wrap:break-word}
html,body{max-width:100%;overflow-x:hidden}
`;
}

/* A marca sai inteira, numa cor so e num tamanho so: a Bevan nao tem segundo
   peso, entao nao ha o que destacar dentro do nome. Nao parte o nome em duas
   cores como a X e a AN, nao desenha glifo como a X, nao pendura algarismo como
   a AV e nao empilha o slogan embaixo como a AV e a AX. O slogan e um elemento
   IRMAO, que vive ao lado e nao dentro da marca, e por isso ele nao entra aqui. */
function baLogo(ctx, cls) {
  const { c, H } = ctx;
  const nome = String(ctx.site.shortName || ctx.site.name).trim();
  return `<a class="${c(cls)}" href="/"><b>${H.esc(nome)}</b></a>`;
}

/* A marcacao de horario, motivo do portal inteiro. O campo `date` chega como
   ISO com fuso Z, entao a hora e trazida para o horario de Brasilia por
   deslocamento fixo de tres horas antes de ser lida. Data sem parte de hora
   devolve string vazia, e nesse caso a chamada simplesmente nao mostra relogio,
   sem quebrar o desenho. */
function baHora(iso) {
  const cru = String(iso || '');
  if (cru.indexOf('T') < 0) return '';
  const t = new Date(cru);
  if (isNaN(t.getTime())) return '';
  const br = new Date(t.getTime() - 3 * 3600 * 1000);
  const hh = String(br.getUTCHours()).padStart(2, '0');
  const mm = String(br.getUTCMinutes()).padStart(2, '0');
  return `${hh}h${mm}`;
}

/* O carimbo de tempo: horario em vermelho e, ao lado, a data curta em cinza.
   Sem horario na origem, sobra so a data. */
function baCarimbo(ctx, a) {
  const { c, H } = ctx;
  const hr = baHora(a.date);
  const dt = H.dateShort(a.date);
  return `<time class="${c('hora')}" datetime="${H.esc(a.date)}">${hr ? H.esc(hr) : H.esc(dt)}`
    + `${hr ? `<u>${H.esc(dt)}</u>` : ''}</time>`;
}

function baHeader(ctx, menu) {
  const { c, H } = ctx;
  const links = (menu || []).map(x => `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  const slogan = ctx.site.tagline
    ? `<span class="${c('slogan')}">${H.esc(ctx.site.tagline)}</span>`
    : '';
  return `<body>
<header class="${c('frontao')}"><div class="${c('frontin')}">
<div class="${c('cume')}">${baLogo(ctx, 'emblema')}${slogan}</div>
<nav class="${c('pauta')}" aria-label="Editorias">${links}</nav>
</div></header>
<main class="${c('banca')}">`;
}

function baFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const eds = (menu || []).map(x => `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `</main>
<footer class="${c('pedestal')}"><div class="${c('pedestin')}">
<div class="${c('pgrade')}">
<div>${baLogo(ctx, 'emblema')}<p class="${c('psobre')}">${H.esc(site.description || site.tagline || '')}</p></div>
<div><h3>Editorias</h3>${eds}</div>
<div><h3>Institucional</h3>${H.instLinks()}</div>
<div><h3>Redação</h3>
<a href="/contato/">Fale com a redação</a>
<a href="/contato/">Sugerir uma pauta</a>
<a href="/contato/">Corrigir uma informação</a>
<a href="/busca/">Buscar no acervo</a></div>
</div>
<div class="${c('pcarimbo')}">&copy; ${H.year()} ${H.esc(site.name)}. Todos os direitos reservados. ${H.esc(site.domain)}</div>
</div></footer>
${H.bodyEnd()}`;
}

/* ---------- auxiliares ---------- */

/* A manchete da coluna larga. A ordem e deliberada: kicker e horario, titulo,
   resumo e SO ENTAO a foto. Sem foto, a peca continua inteira e nao deixa vao. */
function baManchetao(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('manchetao')}" href="${H.url(a)}">`
    + `<span class="k"><span class="${c('etiqueta')}">${H.cat(a)}</span>${baCarimbo(ctx, a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 215))}</span>` : ''}`
    + `${a.image ? `<span class="im">${H.pic(a, true)}</span>` : ''}</a>`;
}

/* Chamada da coluna do meio: kicker, horario, titulo e um resumo curto. Sem foto
   por desenho, para que a coluna larga fique com a unica imagem da abertura. */
function baFlash(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('flash')}" href="${H.url(a)}">`
    + `<span class="k"><span class="${c('etiqueta')}">${H.cat(a)}</span>${baCarimbo(ctx, a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 96))}</span>` : ''}</a>`;
}

/* Linha do minuto a minuto: horario e titulo, e nada mais. E a peca mais densa
   da pagina, e a que carrega o conceito do portal de forma mais literal. */
function baPulso(ctx, a) {
  const { c, H } = ctx;
  return `<a class="${c('pulso')}" href="${H.url(a)}">`
    + `${baCarimbo(ctx, a)}`
    + `<span class="h">${H.esc(a.title)}</span></a>`;
}

/* Cartao da grade de quatro colunas, usado na editoria da home e na leitura
   relacionada. A foto vem em 3/2 com a sombra dura, que troca para o vermelho no
   hover. O carimbo de tempo fecha o cartao. */
function baVerbete(ctx, a, comDek) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('verbete')}" href="${H.url(a)}">`
    + `${a.image ? `<span class="im">${H.pic(a, false)}</span>` : ''}`
    + `<span class="${c('etiqueta')}">${H.cat(a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d && comDek ? `<span class="d">${H.esc(H.corta(d, 118))}</span>` : ''}`
    + `<span class="k">${baCarimbo(ctx, a)}</span></a>`;
}

/* Linha da listagem, com a MINIATURA NO MEIO: campo de tempo, foto e texto.
   Sem foto, a celula do meio fica vazia e a grade nao se desmancha. */
function baTalao(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  const hr = baHora(a.date);
  return `<a class="${c('talao')}" href="${H.url(a)}">`
    + `<span class="k"><b>${H.esc(hr || H.dateShort(a.date))}</b>`
    + `${hr ? `<i>${H.esc(H.dateShort(a.date))}</i>` : ''}</span>`
    + `${a.image ? `<span class="im">${H.pic(a, false)}</span>` : '<span class="im"></span>'}`
    + `<span class="tx"><span class="${c('etiqueta')}">${H.cat(a)}</span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 165))}</span>` : ''}</span></a>`;
}

/* Cabecalho de secao: o fio grosso de 6px por cima e o titulo pousado nele, com
   o link de "ver tudo" encostado a direita na mesma linha de base. */
function baTesteira(ctx, nome, cs) {
  const { c, H } = ctx;
  return `<div class="${c('testeira')}"><h2>${H.esc(nome)}</h2>`
    + `${cs ? `<a class="more" href="${H.curl(cs)}">Tudo em ${H.esc(nome)}</a>` : ''}</div>`;
}

/* ---------- paginas ---------- */

function baHome(ctx, arts, menu) {
  const { c, H } = ctx;
  const pref = ctx.site.heroFrom;
  const fila = pref ? [...arts.filter(a => a.category && a.category.slug === pref),
                       ...arts.filter(a => !a.category || a.category.slug !== pref)] : arts;

  // abertura: manchete na coluna larga, tres chamadas no meio, seis linhas de
  // minuto a minuto na estreita. Cada coluna aceita ZERO itens e some sozinha:
  // com um unico artigo no acervo a home ainda sai inteira.
  const lead = fila[0];
  const meio = fila.slice(1, 4);
  const pulsos = fila.slice(4, 10);

  const faltas = `${meio.length ? '' : ` ${c('sem2')}`}${pulsos.length ? '' : ` ${c('sem3')}`}`;
  const colMeio = meio.length
    ? `<div class="${c('curso')}">${meio.map(a => baFlash(ctx, a)).join('')}</div>`
    : '';
  const colPulso = pulsos.length
    ? `<aside class="${c('minuto')}" aria-label="Minuto a minuto"><b>Minuto a minuto</b>`
      + pulsos.map(a => baPulso(ctx, a)).join('') + `</aside>`
    : '';
  const abertura = lead
    ? `<section class="${c('plantao')}${faltas}">${baManchetao(ctx, lead)}${colMeio}${colPulso}</section>`
    : '';

  const usados = new Set([lead, ...meio, ...pulsos].filter(Boolean).map(a => a.slug));
  const rest = fila.slice(10);
  const byCat = new Map();
  const fixas = Array.isArray(ctx.site.homeSections) ? ctx.site.homeSections : null;
  if (fixas) {
    for (const cs of fixas) {
      const itens = arts.filter(a => a.category && a.category.slug === cs && !usados.has(a.slug));
      if (itens.length) byCat.set(cs, { name: itens[0].category.name, items: itens });
    }
  } else {
    for (const a of rest) {
      if (usados.has(a.slug)) continue;
      const cs = a.category ? a.category.slug : 'noticias';
      if (!byCat.has(cs)) byCat.set(cs, { name: a.category ? a.category.name : 'Notícias', items: [] });
      byCat.get(cs).items.push(a);
    }
  }

  // cada editoria em grade de quatro cartoes, e BASTA UM para o bloco existir:
  // exigir a grade cheia apagaria a editoria mais nova do portal
  const vistos = new Set();
  const blocos = [...byCat.entries()]
    .map(([cs, v]) => [cs, v, v.items.filter(a => !vistos.has(a.slug)).slice(0, 4)])
    .filter(([, , q]) => q.length >= 1)
    .slice(0, 8)
    .map(([cs, v, q]) => {
      q.forEach(a => vistos.add(a.slug));
      return `<section class="${c('lance')}">${baTesteira(ctx, v.name, cs)}`
        + `<div class="${c('quadra')}">${q.map(a => baVerbete(ctx, a, true)).join('')}</div></section>`;
    }).join('\n');

  return `${H.head(ctx, H.homeMeta(ctx.site))}
${baHeader(ctx, menu)}
${H.h1(ctx)}
${abertura}
${blocos}
${baFooter(ctx, menu)}`;
}

function baArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;

  // Todo h2 recebe id, para ancora direta. Mas so o h2 anterior ao ULTIMO
  // fechamento de paragrafo do corpo ganha o atributo que liga a sombra dura do
  // titulo: o titulo de qualquer bloco anexado depois do texto ficaria marcado
  // como secao da materia se entrasse na conta.
  const cru = String(art.content);
  const fimTexto = cru.lastIndexOf('</p>');
  let n = 0;
  let corpo = cru.replace(/<h2\b([^>]*)>([\s\S]*?)<\/h2>/gi, (m, attrs, txt, offset) => {
    if (/\bid=/.test(attrs)) return m;
    const rotulo = txt.replace(/<[^>]+>/g, '').trim();
    if (!rotulo) return m;
    n += 1;
    const doTexto = fimTexto < 0 || offset < fimTexto;
    return `<h2 id="p${n}"${doTexto ? ' data-e="1"' : ''}${attrs}>${txt}</h2>`;
  });

  // conteudo largo rola dentro do proprio conteiner, nunca a pagina inteira
  corpo = corpo
    .replace(/<table\b[\s\S]*?<\/table>/gi, m => `<div class="${c('transborda')}">${m}</div>`)
    .replace(/<pre\b[\s\S]*?<\/pre>/gi, m => `<div class="${c('transborda')}">${m}</div>`);

  const hr = baHora(art.date);
  const linhaMeta = `${H.esc(P.dstr)}${hr ? `, ${H.esc(hr)}` : ''} &middot; ${P.readMin} min de leitura`;

  const eq = (ctx.site.equipe || []).find(x => x.nome === art.author);
  const autor = eq
    ? `<a class="${c('assina')}" rel="author" href="/autor/${H.esc(eq.slug)}/"><img src="/img/autores/${H.esc(eq.slug)}.webp" width="46" height="46" alt="" loading="lazy"><span><b>${H.esc(eq.nome)}</b><i>${linhaMeta}</i></span></a>`
    : `<span class="${c('assina')}"><span><b>${H.esc(art.author || ctx.site.name)}</b><i>${linhaMeta}</i></span></span>`;

  const fig = art.image
    ? `<figure class="${c('cliche')}">${H.pic(art, true)}${art.image.caption ? `<figcaption>${H.esc(art.image.caption)}</figcaption>` : ''}</figure>`
    : '';

  const rel = (related && related.length)
    ? `<section class="${c('emseguida')}">${baTesteira(ctx, 'Leia agora', '')}`
      + `<div class="${c('emseguidag')}">${related.slice(0, 3).map(a => baVerbete(ctx, a, false)).join('')}</div></section>`
    : '';

  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${baHeader(ctx, menu)}
<article class="${c('impresso')}">
${H.crumbs(ctx, art, P)}
<div class="${c('cabeco')}">
<span class="${c('etiqueta')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<span class="${c('sutia')}">${H.esc(art.dek)}</span>` : ''}
${autor}
</div>
<span class="${c('fiogrosso')}"></span>
${fig}
<div class="${c('materia')}">${corpo}</div>
</article>
${rel}
${baFooter(ctx, menu)}`;
}

function baList(ctx, opts) {
  const { c, H } = ctx;
  const itens = opts.items || [];
  return `${H.head(ctx, H.listMeta(ctx, opts))}
${baHeader(ctx, opts.menu)}
${baTesteira(ctx, opts.title, '')}
<div class="${c('arquivo')}">${itens.map(a => baTalao(ctx, a)).join('')}</div>
${baFooter(ctx, opts.menu)}`;
}


/* ===================== ARCH BC =====================
   Portal: noticiasdiarios.com  ("Notícias Diários", Registro do dia)

   Conceito: PAINEL DO DIA. O portal e de servico, e servico se le em bloco, nao
   em fio de leitura. Entao a pagina e uma GRADE DE CARTOES COM MOLDURA, densa e
   de alto contraste, e o unico elemento grafico e a BARRA DE ACENTO: um retangulo
   solido de 4px que abre cada titulo de editoria e volta como filete no cartao em
   destaque.

   Deliberadamente o oposto da AX, que este portal usava antes:
   - a AX punha um fio vertical continuo de margem de caderno atravessando a
     pagina inteira, e nao tinha cartao, nem moldura, nem fundo: separava por ar.
     Aqui nao ha fio vertical nenhum, e TUDO e cartao com moldura de 1px;
   - a AX tinha cabecalho em papel creme com a marca por cima da margem. Aqui o
     cabecalho e uma FAIXA ESCURA de sangria total, com a marca e as editorias na
     mesma linha de base;
   - a AX abria com foto em cima e texto embaixo, em coluna unica. Aqui a abertura
     e PARTIDA: foto grande a esquerda e texto a direita, lado a lado;
   - a AX indentava tudo 94px para depois da margem. Aqui a grade ocupa a largura
     inteira do papel, em 3 e 4 colunas;
   - a AX escrevia a data em italico de display numa calha de 70px. Aqui a data e
     versal minuscula ao lado da editoria, dentro do cartao.

   A chave tem DUAS letras: o deploy precisa casar a marca `ARCH BC` inteira,
   nunca so `ARCH B`.
*/
function bcCss(ctx) {
  const { s } = ctx;
  return `
:root{
--bcac:var(--p);--bcink:var(--ink);--bcpaper:var(--paper);
--bcfio:color-mix(in srgb,var(--ink) 14%,transparent);
--bcfio2:color-mix(in srgb,var(--ink) 8%,transparent);
--bcfraco:color-mix(in srgb,var(--ink) 52%,transparent);
--bccard:#ffffff;
--bcpad:24px;--bcgap:26px
}
body{background:var(--bcpaper);color:var(--bcink)}
${s('folha')}{max-width:var(--maxw);margin:0 auto;padding:0 var(--bcpad);box-sizing:border-box;width:100%}
${s('folha')} > *{min-width:0}

/* ---------- cabecalho: faixa escura de sangria total ---------- */
${s('barra')}{background:var(--bar-bg);color:var(--bar-tx)}
${s('barrain')}{max-width:var(--maxw);margin:0 auto;padding:18px var(--bcpad);box-sizing:border-box;display:flex;align-items:baseline;gap:14px 34px;flex-wrap:wrap}
${s('marca')}{display:inline-flex;align-items:baseline;gap:11px;text-decoration:none;color:inherit;flex:none}
${s('marca')} b{font-family:var(--fd);font-weight:700;font-size:27px;line-height:1;letter-spacing:-.022em;color:var(--bar-tx)}
${s('marca')} i{font-style:normal;font-family:var(--fb);font-size:10px;font-weight:600;letter-spacing:.2em;color:color-mix(in srgb,var(--bar-tx) 62%,transparent)}
${s('marca')}:hover b{color:var(--bcac)}
${s('nav')}{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px 22px;margin-left:auto}
${s('nav')} a{font-family:var(--fb);font-size:13.5px;font-weight:500;color:color-mix(in srgb,var(--bar-tx) 84%,transparent);text-decoration:none;padding:3px 0;border-bottom:2px solid transparent;transition:color .16s ease,border-color .16s ease}
${s('nav')} a:hover{color:var(--bar-tx);border-bottom-color:var(--bcac)}

/* ---------- atomos ---------- */
${s('kick')}{display:inline-flex;align-items:center;gap:9px;font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:var(--kls);color:var(--bcac)}
${s('kick')} span{color:var(--bcfraco);font-weight:500;letter-spacing:.08em}
${s('kick')} a{color:inherit;text-decoration:none}

/* o titulo de editoria abre com a BARRA DE ACENTO, que e o motivo grafico unico */
${s('sec')}{display:flex;align-items:center;justify-content:space-between;gap:10px 20px;flex-wrap:wrap;margin:0 0 18px;padding-left:16px;position:relative}
${s('sec')}::before{content:"";position:absolute;left:0;top:2px;bottom:2px;width:4px;background:var(--bcac)}
${s('sec')} h2{font-family:var(--fd);font-weight:700;font-size:clamp(20px,2.1vw,26px);line-height:1.2;letter-spacing:-.017em;color:var(--bcink);margin:0;text-align:left}
${s('sec')} .more{font-family:var(--fb);font-size:12.5px;font-weight:600;color:var(--bcfraco);text-decoration:none;border-bottom:1px solid var(--bcfio);padding-bottom:2px}
${s('sec')} .more:hover{color:var(--bcac);border-bottom-color:var(--bcac)}
${s('bloco')}{margin:0 0 46px}

/* ---------- a abertura PARTIDA: foto a esquerda, texto a direita ---------- */
${s('abre')}{display:grid;grid-template-columns:1.15fr .85fr;gap:0;margin:26px 0 40px;border:1px solid var(--bcfio);background:var(--bccard);text-decoration:none;color:inherit}
${s('abre')} .im{display:block;overflow:hidden;background:var(--ph);aspect-ratio:16/10;min-height:100%}
${s('abre')} .im img{width:100%;height:100%;object-fit:cover;display:block}
${s('abre')} .tx{display:flex;flex-direction:column;justify-content:center;gap:14px;padding:34px 32px;border-left:4px solid var(--bcac);text-align:left}
${s('abre')} .h{font-family:var(--fd);font-weight:700;font-size:clamp(25px,2.9vw,37px);line-height:1.14;letter-spacing:-.021em;color:var(--bcink);margin:0;text-align:left}
${s('abre')}:hover .h{color:var(--bcac)}
${s('abre')} .d{font-family:var(--fb);font-size:16px;font-weight:400;line-height:1.7;color:var(--bcfraco);margin:0;text-align:left}

/* ---------- a grade de cartoes ---------- */
${s('grade')}{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--bcgap)}
${s('grade4')}{grid-template-columns:repeat(4,minmax(0,1fr))}
${s('cartao')}{display:flex;flex-direction:column;border:1px solid var(--bcfio);background:var(--bccard);text-decoration:none;color:inherit;transition:border-color .18s ease,transform .18s ease}
${s('cartao')}:hover{border-color:var(--bcac);transform:translateY(-2px)}
${s('cartao')} .im{display:block;width:100%;aspect-ratio:var(--card-ar);overflow:hidden;background:var(--ph)}
${s('cartao')} .im img{width:100%;height:100%;object-fit:cover;display:block}
${s('cartao')} .tx{display:flex;flex-direction:column;gap:9px;padding:16px 17px 19px;text-align:left}
${s('cartao')} .h{font-family:var(--fd);font-weight:600;font-size:18px;line-height:1.28;letter-spacing:-.012em;color:var(--bcink);margin:0;text-align:left}
${s('cartao')}:hover .h{color:var(--bcac)}
${s('cartao')} .d{font-family:var(--fb);font-size:14px;font-weight:400;line-height:1.66;color:var(--bcfraco);margin:0;text-align:left}

/* ---------- artigo: calha de apoio a esquerda, texto a direita ---------- */
${s('peca')}{display:grid;grid-template-columns:186px minmax(0,1fr);gap:0 40px;margin:26px 0 0;align-items:start}
${s('calha')}{position:sticky;top:18px;display:flex;flex-direction:column;gap:16px;padding-right:18px;border-right:1px solid var(--bcfio);text-align:left}
${s('corpo')}{min-width:0}
${s('corpo')} h1{font-family:var(--fd);font-weight:700;font-size:clamp(27px,3.2vw,41px);line-height:1.13;letter-spacing:-.023em;color:var(--bcink);margin:0 0 14px;text-align:left}
${s('dek')}{display:block;font-family:var(--fb);font-size:18px;font-weight:400;line-height:1.66;color:var(--bcfraco);margin:0 0 20px;max-width:62ch;text-align:left}
${s('gravura')}{margin:0 0 24px}
${s('gravura')} img{width:100%;display:block;border:1px solid var(--bcfio)}
${s('gravura')} figcaption{font-family:var(--fb);font-size:12.5px;line-height:1.66;color:var(--bcfraco);padding:9px 0 0;text-align:left}
${s('pena')}{display:flex;align-items:center;gap:11px;text-decoration:none;color:inherit}
${s('pena')} img{width:40px;height:40px;object-fit:cover;background:var(--ph);flex:none}
${s('pena')} b{display:block;font-family:var(--fd);font-weight:700;font-size:15px;line-height:1.24;color:var(--bcink)}
${s('pena')}:hover b{color:var(--bcac)}
${s('pena')} i{display:block;font-style:normal;font-family:var(--fb);font-size:11px;font-weight:500;letter-spacing:.1em;color:var(--bcfraco);margin-top:4px}
${s('data')}{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.06em;color:var(--bcfraco);}

${s('texto')}{font-family:var(--fb);font-size:17.5px;line-height:1.78;color:var(--bcink);max-width:68ch}
${s('texto')} p{margin:0 0 1.25em;text-align:left}
${s('texto')} h2{font-family:var(--fd);font-weight:700;font-size:25px;line-height:1.24;letter-spacing:-.016em;color:var(--bcink);margin:2em 0 .6em;padding-left:14px;border-left:4px solid var(--bcac);scroll-margin-top:20px;text-align:left}
${s('texto')} h3{font-family:var(--fd);font-weight:600;font-size:19.5px;line-height:1.32;color:var(--bcink);margin:1.7em 0 .5em;scroll-margin-top:20px;text-align:left}
${s('texto')} a{color:var(--bcac);text-decoration:underline;text-underline-offset:3px}
${s('texto')} ul,${s('texto')} ol{margin:0 0 1.25em;padding-left:1.35em;text-align:left}
${s('texto')} li{margin-bottom:.5em}
${s('texto')} img{max-width:100%;height:auto;display:block;margin:1.6em 0}
${s('texto')} blockquote{margin:1.8em 0;padding:2px 0 2px 20px;border-left:4px solid var(--bcac);font-family:var(--fd);font-size:20px;line-height:1.5;color:var(--bcink);text-align:left}
${s('texto')} blockquote p{margin:0;font:inherit;text-align:left}
/* a TABELA e o conteudo principal destes artigos: ela sai da medida do texto e
   avanca sobre a faixa livre a direita, com cabecalho preso no topo ao rolar */
${s('escoa')}{display:block;overflow-x:auto;-webkit-overflow-scrolling:touch;margin:1.7em 0;width:min(calc(100% + 190px),calc(100vw - 130px));max-width:none;border:1px solid var(--bcfio);background:var(--bccard)}
${s('texto')} table{width:100%;border-collapse:collapse;font-family:var(--fb);font-size:14.5px;min-width:460px}

/* tabela vira cartao no celular: sem isto ela sai da tela e o gesto de
   arrastar nao e descoberto. thead sai da tela mas continua no DOM */
@media(max-width:640px){
  ${s('texto')} .tabwrap{overflow:visible;border:0;background:transparent}
  ${s('texto')} table{min-width:0;display:block;width:auto;overflow:visible}
  ${s('texto')} table caption{display:none}
  ${s('texto')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('texto')} table tbody,${s('texto')} table tr,
  ${s('texto')} table th,${s('texto')} table td{display:block;width:auto}
  ${s('texto')} table tbody tr{background:rgba(255,255,255,.6);border:1px solid rgba(0,0,0,.12);
    border-radius:12px;padding:2px 16px 14px;margin-bottom:12px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('texto')} table tbody th,${s('texto')} table tbody td{border:0;background:transparent;padding:0}
  ${s('texto')} table tbody th{border-bottom:1px solid rgba(0,0,0,.12);padding:13px 0 11px;
    font-weight:700;text-align:left}
  ${s('texto')} table tbody td{padding:12px 0 0;text-align:left;line-height:1.5}
  ${s('texto')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;opacity:.62;margin-bottom:2px}
}
${s('texto')} th,${s('texto')} td{padding:11px 14px;border-bottom:1px solid var(--bcfio2);text-align:left}
${s('texto')} thead th{font-size:10.5px;font-weight:700;letter-spacing:.13em;color:var(--bcfraco);background:color-mix(in srgb,var(--p) 6%,transparent);border-bottom:1px solid var(--bcfio)}
${s('texto')} tbody tr:last-child td{border-bottom:0}
${s('texto')} pre{margin:0;padding:16px 18px;background:color-mix(in srgb,var(--ink) 5%,transparent);font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;line-height:1.62}
${s('texto')} code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:.88em;background:color-mix(in srgb,var(--ink) 6%,transparent);padding:2px 5px}
${s('recado')}{display:flex;align-items:center;flex-wrap:wrap;gap:10px 16px;margin:16px 0 0}
${s('recado')} a{font-family:var(--fb);font-size:11.5px;font-weight:700;letter-spacing:.1em;color:var(--bcac);text-decoration:none;border:1px solid var(--bcfio);padding:7px 12px;transition:border-color .16s ease,background .16s ease}
${s('recado')} a:hover{border-color:var(--bcac);background:color-mix(in srgb,var(--p) 7%,transparent)}
${s('vizinho')}{margin:52px 0 0}

/* ---------- paginas de equipe e de autor ----------
   Estas classes vem do HTML das paginas extras e o motor as renomeia com o mesmo
   mapa do CSS, entao o seletor precisa ser LITERAL aqui: passar pelo helper s()
   geraria outro nome, porque s() usa outra funcao de hash. */
.eq-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:24px 0 12px}
.eq-card{display:grid;grid-template-columns:76px minmax(0,1fr);gap:0 16px;align-items:start;border:1px solid var(--bcfio);background:var(--bccard);padding:16px;text-decoration:none;color:inherit}
.eq-card:hover{border-color:var(--bcac)}
.eq-card img{width:76px;height:76px;object-fit:cover;background:var(--ph);display:block}
.eq-card b,.eq-card h3{font-family:var(--fd);font-weight:700;font-size:17px;line-height:1.24;color:var(--bcink);margin:0 0 6px}
.eq-card:hover b,.eq-card:hover h3{color:var(--bcac)}
.eq-area{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.15em;color:var(--bcac);margin:0 0 7px}
.eq-res{display:block;font-family:var(--fb);font-size:13.5px;line-height:1.66;color:var(--bcfraco);margin:0;text-align:left}
.pf-topo{display:flex;gap:18px;align-items:center;margin:0 0 26px;padding:18px;border:1px solid var(--bcfio);background:var(--bccard)}
.pf-topo img{width:92px;height:92px;object-fit:cover;flex:none;background:var(--ph)}
.pf-ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.15em;color:var(--bcac);margin:0 0 8px}
.pf-lead{font-family:var(--fd);font-weight:600;font-size:19px;line-height:1.34;color:var(--bcink);margin:0;text-align:left}
.pf-obs{font-family:var(--fb);font-size:13.5px;line-height:1.7;color:var(--bcfraco);padding-left:16px;border-left:3px solid var(--bcfio);margin:26px 0 0;text-align:left}

/* ---------- rodape ---------- */
${s('rodape')}{background:var(--footer-bg);color:var(--footer-tx);margin-top:64px}
${s('rodapein')}{max-width:var(--maxw);margin:0 auto;padding:44px var(--bcpad) 26px;box-sizing:border-box}
${s('rgrid')}{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:32px;margin-bottom:28px}
${s('rodape')} ${s('marca')} b{color:#fff}
${s('rodape')} ${s('marca')} i{color:var(--footer-tx)}
${s('rsobre')}{font-family:var(--fb);font-size:13.5px;line-height:1.72;color:var(--footer-tx);margin-top:14px;max-width:40ch;text-align:left}
${s('rgrid')} h3{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.15em;color:#fff;margin:0 0 12px}
${s('rgrid')} a{display:block;font-family:var(--fb);font-size:13.5px;color:var(--footer-tx);text-decoration:none;padding:5px 0}
${s('rgrid')} a:hover{color:#fff}
${s('rbase')}{border-top:1px solid color-mix(in srgb,var(--footer-tx) 22%,transparent);padding-top:18px;font-family:var(--fb);font-size:12.5px;line-height:1.72;color:var(--footer-tx);text-align:left}

@media(max-width:1040px){
${s('grade')}{grid-template-columns:repeat(2,minmax(0,1fr))}
${s('grade4')}{grid-template-columns:repeat(2,minmax(0,1fr))}
${s('peca')}{grid-template-columns:150px minmax(0,1fr);gap:0 26px}
${s('escoa')}{width:100%}
${s('rgrid')}{grid-template-columns:1fr 1fr;gap:26px}
}
@media(max-width:760px){
${s('abre')}{grid-template-columns:minmax(0,1fr)}
${s('abre')} .im{aspect-ratio:16/9;min-height:0}
${s('abre')} .tx{padding:22px 20px;border-left:0;border-top:4px solid var(--bcac)}
${s('peca')}{grid-template-columns:minmax(0,1fr);gap:18px}
${s('calha')}{position:static;flex-direction:row;align-items:center;flex-wrap:wrap;gap:14px 20px;padding:0 0 16px;border-right:0;border-bottom:1px solid var(--bcfio)}
${s('texto')}{font-size:16.5px}
${s('texto')} h2{font-size:22px}
${s('barrain')}{padding:14px var(--bcpad)}
${s('marca')} b{font-size:23px}
${s('nav')}{margin-left:0;width:100%;gap:8px 18px}
${s('rgrid')}{grid-template-columns:1fr 1fr;gap:22px}
}
@media(max-width:520px){
${s('folha')},${s('barrain')},${s('rodapein')}{padding-left:16px;padding-right:16px}
${s('grade')},${s('grade4')}{grid-template-columns:minmax(0,1fr);gap:18px}
${s('nav')}{flex-wrap:nowrap;overflow-x:auto}
${s('nav')} a{white-space:nowrap}
${s('rgrid')}{grid-template-columns:1fr;gap:20px}
}
${s('cartao')} > *,${s('grade')} > *{min-width:0}
${s('cartao')} .h,${s('abre')} .h,${s('corpo')} h1,${s('sec')} h2{overflow-wrap:break-word}
html,body{max-width:100%;overflow-x:hidden}
`;
}

function bcLogo(ctx, cls) {
  const { c, H } = ctx;
  const nome = String(ctx.site.shortName || ctx.site.name).trim();
  const tag = ctx.site.tagline ? `<i>${H.esc(ctx.site.tagline)}</i>` : '';
  return `<a class="${c(cls)}" href="/"><b>${H.esc(nome)}</b>${tag}</a>`;
}

function bcHeader(ctx, menu) {
  const { c, H } = ctx;
  const links = (menu || []).map(m => `<a href="${H.curl(m.slug)}">${H.esc(m.name)}</a>`).join('');
  return `<body>
<header class="${c('barra')}"><div class="${c('barrain')}">
${bcLogo(ctx, 'marca')}
<nav class="${c('nav')}" aria-label="Editorias">${links}</nav>
</div></header>
<main class="${c('folha')}">`;
}

function bcFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const eds = (menu || []).map(m => `<a href="${H.curl(m.slug)}">${H.esc(m.name)}</a>`).join('');
  return `</main>
<footer class="${c('rodape')}"><div class="${c('rodapein')}">
<div class="${c('rgrid')}">
<div>${bcLogo(ctx, 'marca')}<p class="${c('rsobre')}">${H.esc(site.description || site.tagline || '')}</p></div>
<div><h3>Editorias</h3>${eds}</div>
<div><h3>Institucional</h3>${H.instLinks()}</div>
<div><h3>Redação</h3>
<a href="/contato/">Fale com a redação</a>
<a href="/contato/">Sugerir uma pauta</a>
<a href="/contato/">Corrigir uma informação</a>
<a href="/busca/">Buscar no acervo</a></div>
</div>
<div class="${c('rbase')}">&copy; ${H.year()} ${H.esc(site.name)}. Todos os direitos reservados. ${H.esc(site.domain)}</div>
</div></footer>
${H.bodyEnd()}`;
}

/* O cartao e a unidade da pagina: moldura de 1px, foto em cima, editoria e data
   na mesma linha, titulo e resumo. Sem foto ele continua cartao, so mais curto. */
function bcCard(ctx, a) {
  const { c, H } = ctx;
  const d = (a.dek || a.excerpt || '').trim();
  return `<a class="${c('cartao')}" href="${H.url(a)}">`
    + `${a.image ? `<span class="im">${H.pic(a, false)}</span>` : ''}`
    + `<span class="tx">`
    + `<span class="${c('kick')}">${H.cat(a)}<span>${H.esc(H.dateShort(a.date))}</span></span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 108))}</span>` : ''}`
    + `</span></a>`;
}

function bcSecHead(ctx, nome, cs) {
  const { c, H } = ctx;
  return `<div class="${c('sec')}"><h2>${H.esc(nome)}</h2>`
    + `${cs ? `<a class="more" href="${H.curl(cs)}">Ver tudo em ${H.esc(nome)}</a>` : ''}</div>`;
}

function bcHome(ctx, arts, menu) {
  const { c, H } = ctx;
  const pref = ctx.site.heroFrom;
  const fila = pref ? [...arts.filter(a => a.category && a.category.slug === pref),
                       ...arts.filter(a => !a.category || a.category.slug !== pref)] : arts;

  const top = fila[0];
  const dTop = top ? (top.dek || top.excerpt || '').trim() : '';
  const abre = top
    ? `<a class="${c('abre')}" href="${H.url(top)}">`
      + `${top.image ? `<span class="im">${H.pic(top, true)}</span>` : ''}`
      + `<span class="tx"><span class="${c('kick')}">${H.cat(top)}<span>${H.esc(H.dateShort(top.date))}</span></span>`
      + `<span class="h">${H.esc(top.title)}</span>`
      + `${dTop ? `<span class="d">${H.esc(H.corta(dTop, 190))}</span>` : ''}`
      + `</span></a>`
    : '';

  const usados = new Set(top ? [top.slug] : []);
  const destaques = fila.filter(a => !usados.has(a.slug)).slice(0, 6);
  destaques.forEach(a => usados.add(a.slug));
  const grade = destaques.length
    ? `<section class="${c('bloco')}">${bcSecHead(ctx, 'Últimas do dia', '')}`
      + `<div class="${c('grade')}">${destaques.map(a => bcCard(ctx, a)).join('')}</div></section>`
    : '';

  const byCat = new Map();
  const fixas = Array.isArray(ctx.site.homeSections) ? ctx.site.homeSections : null;
  if (fixas) {
    for (const cs of fixas) {
      const itens = arts.filter(a => a.category && a.category.slug === cs && !usados.has(a.slug));
      if (itens.length) byCat.set(cs, { name: itens[0].category.name, items: itens });
    }
  } else {
    for (const a of fila) {
      if (usados.has(a.slug)) continue;
      const cs = a.category ? a.category.slug : 'noticias';
      if (!byCat.has(cs)) byCat.set(cs, { name: a.category ? a.category.name : 'Notícias', items: [] });
      byCat.get(cs).items.push(a);
    }
  }

  const vistos = new Set();
  const blocos = [...byCat.entries()]
    .map(([cs, v]) => [cs, v, v.items.filter(a => !vistos.has(a.slug)).slice(0, 4)])
    .filter(([, , q]) => q.length >= 1)
    .slice(0, 7)
    .map(([cs, v, q]) => {
      q.forEach(a => vistos.add(a.slug));
      return `<section class="${c('bloco')}">${bcSecHead(ctx, v.name, cs)}`
        + `<div class="${c('grade')} ${c('grade4')}">${q.map(a => bcCard(ctx, a)).join('')}</div></section>`;
    }).join('\n');

  return `${H.head(ctx, H.homeMeta(ctx.site))}
${bcHeader(ctx, menu)}
${H.h1(ctx)}
${abre}
${grade}
${blocos}
${bcFooter(ctx, menu)}`;
}

function bcArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;

  const cru = String(art.content);
  const fimTexto = cru.lastIndexOf('</p>');
  let n = 0;
  let corpo = cru.replace(/<h2\b([^>]*)>([\s\S]*?)<\/h2>/gi, (m, attrs, txt, offset) => {
    if (/\bid=/.test(attrs)) return m;
    const rotulo = txt.replace(/<[^>]+>/g, '').trim();
    if (!rotulo) return m;
    n += 1;
    const doTexto = fimTexto < 0 || offset < fimTexto;
    return `<h2 id="p${n}"${doTexto ? ' data-a="1"' : ''}${attrs}>${txt}</h2>`;
  });
  corpo = corpo
    .replace(/<table\b[\s\S]*?<\/table>/gi, m => `<div class="${c('escoa')}">${m}</div>`)
    .replace(/<pre\b[\s\S]*?<\/pre>/gi, m => `<div class="${c('escoa')}">${m}</div>`);

  const eq = (ctx.site.equipe || []).find(x => x.nome === art.author);
  const autor = eq
    ? `<a class="${c('pena')}" rel="author" href="/autor/${H.esc(eq.slug)}/"><img src="/img/autores/${H.esc(eq.slug)}.webp" width="40" height="40" alt="" loading="lazy"><span><b>${H.esc(eq.nome)}</b><i>${P.readMin} min de leitura</i></span></a>`
    : `<span class="${c('pena')}"><span><b>${H.esc(art.author || ctx.site.name)}</b><i>${P.readMin} min de leitura</i></span></span>`;

  const u = encodeURIComponent(P.absUrl), t = encodeURIComponent(art.title);
  const compart = `<div class="${c('recado')}">`
    + `<a href="https://api.whatsapp.com/send/?text=${t}%20${u}" target="_blank" rel="noopener">WhatsApp</a>`
    + `<a href="https://www.facebook.com/sharer/sharer.php?u=${u}" target="_blank" rel="noopener">Facebook</a>`
    + `<a href="https://twitter.com/intent/tweet?url=${u}&text=${t}" target="_blank" rel="noopener">X</a></div>`;

  const fig = art.image
    ? `<figure class="${c('gravura')}">${H.pic(art, true)}${art.image.caption ? `<figcaption>${H.esc(art.image.caption)}</figcaption>` : ''}</figure>`
    : '';

  const rel = (related && related.length)
    ? `<section class="${c('vizinho')}">${bcSecHead(ctx, 'Leia também', '')}`
      + `<div class="${c('grade')}">${related.slice(0, 3).map(a => bcCard(ctx, a)).join('')}</div></section>`
    : '';

  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${bcHeader(ctx, menu)}
${H.progressBar(ctx)}
${H.crumbs(ctx, art, P)}
<article class="${c('peca')}">
<aside class="${c('calha')}">
<span class="${c('kick')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<span class="${c('data')}">${H.esc(P.dstr)}</span>
${autor}
${compart}
</aside>
<div class="${c('corpo')}">
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<span class="${c('dek')}">${H.esc(art.dek)}</span>` : ''}
${fig}
<div class="${c('texto')}">${corpo}</div>
</div>
</article>
${rel}
${bcFooter(ctx, menu)}
${H.progressScript(ctx)}`;
}

function bcList(ctx, opts) {
  const { c, H } = ctx;
  const itens = opts.items || [];
  return `${H.head(ctx, H.listMeta(ctx, opts))}
${bcHeader(ctx, opts.menu)}
${bcSecHead(ctx, opts.title, '')}
<div class="${c('grade')}">${itens.map(a => bcCard(ctx, a)).join('')}</div>
${bcFooter(ctx, opts.menu)}`;
}


/* ===================== ARCH BD =====================
   Portal: seuguiadesaude.com.br  ("Seu Guia de Saúde")

   Conceito: FICHARIO. O portal nao e noticiario, e consulta: o leitor chega do
   Google com uma duvida objetiva (para que serve, quanto custa, faz mal) e quer
   achar a resposta e sair. Entao a pagina se organiza como uma FICHA, e o unico
   motivo grafico e o INDICE NUMERADO: um numero de dois digitos na cor de
   acento, que abre cada chamada e volta como contador nos subtitulos do artigo.

   Deliberadamente diferente da BC, que e a vizinha mais proxima na tabela:
   - a BC tem cabecalho em FAIXA ESCURA de sangria total. Aqui o cabecalho e
     claro, em duas linhas, com a marca em cima e as editorias embaixo,
     separadas por um filete;
   - a BC embrulha TUDO em cartao com moldura de 1px. Aqui nao existe moldura
     nenhuma: o que separa e filete horizontal e ar;
   - a BC abre com a foto A ESQUERDA e o texto a direita. Aqui e o contrario,
     texto a esquerda e foto a direita, que e a ordem que o CLAUDE.md pede;
   - a BC monta grade de 3 e 4 colunas de cartao vertical. Aqui a grade e de 2
     colunas de ficha DEITADA, miniatura a esquerda e texto a direita;
   - a BC nao numera nada. Aqui o indice de dois digitos e o assunto da pagina.

   A chave tem DUAS letras: o deploy precisa casar a marca ARCH BD inteira,
   nunca so ARCH B.

   Nao existe aria-expanded no cabecalho de proposito: e o motor que injeta o
   menu sanfonado, no funil unico, e ele desiste se achar um. Ver _menuSanfona
   no render.js.
*/
function bdCss(ctx) {
  const { s, c } = ctx;
  return `
:root{
--bdac:var(--p);--bdink:var(--ink);--bdpaper:var(--paper);
--bdfio:color-mix(in srgb,var(--ink) 13%,transparent);
--bdfio2:color-mix(in srgb,var(--ink) 7%,transparent);
/* 65% e o piso: a 55% a razao com o papel cai para 3,69:1, abaixo da regua,
   e este e o tom do resumo, da data e do rodape, ou seja, meia pagina */
--bdfraco:color-mix(in srgb,var(--ink) 70%,transparent);
--bdlavado:color-mix(in srgb,var(--p) 7%,var(--paper));
--bdpad:22px;--bdgap:30px
}
body{background:var(--bdpaper);color:var(--bdink)}
${s('folha')}{max-width:var(--maxw);margin:0 auto;padding:0 var(--bdpad);box-sizing:border-box;width:100%}
${s('folha')} > *{min-width:0}

/* ---------- cabecalho claro, em duas linhas ---------- */
${s('topo')}{background:var(--bdpaper);border-bottom:1px solid var(--bdfio)}
${s('topoin')}{max-width:var(--maxw);margin:0 auto;padding:20px var(--bdpad) 0;box-sizing:border-box}
${s('linha1')}{display:flex;align-items:center;gap:14px 20px}
${s('marca')}{display:inline-flex;align-items:center;gap:12px;text-decoration:none;color:inherit;flex:none}
${s('marca')} ${s('sim')}{display:block;flex:none;line-height:0}
${s('marca')} ${s('sim')} svg{display:block;width:44px;height:44px}
${s('marca')} ${s('nom')}{display:flex;flex-direction:column;gap:3px;min-width:0}
${s('marca')} b{font-family:var(--fd);font-weight:700;font-size:26px;line-height:1.05;letter-spacing:-.024em;color:var(--bdink);white-space:nowrap}
/* a ultima palavra do nome carrega a cor da marca, como a metade de baixo da
   capsula carrega o tom claro */
${s('marca')} b em{font-style:normal;color:var(--bdac)}
${s('marca')} i{font-style:normal;font-family:var(--fb);font-size:9.5px;font-weight:600;letter-spacing:.2em;color:var(--bdfraco);white-space:nowrap}
${s('marca')}:hover b{color:var(--bdac)}
${s('marca')}:hover ${s('sim')} svg{transform:translateY(-1px)}
${s('marca')} ${s('sim')} svg{transition:transform .18s ease}
${s('nav')}{display:flex;flex-wrap:wrap;align-items:center;gap:2px 26px;margin:16px 0 0;padding:12px 0 0;border-top:1px solid var(--bdfio2)}
${s('nav')} a{font-family:var(--fb);font-size:13.5px;font-weight:500;color:var(--bdfraco);text-decoration:none;padding:6px 0;position:relative;transition:color .16s ease}
${s('nav')} a::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--bdac);transform:scaleX(0);transform-origin:left;transition:transform .16s ease}
${s('nav')} a:hover{color:var(--bdink)}
${s('nav')} a:hover::after{transform:scaleX(1)}

/* ---------- atomos ---------- */
/* o INDICE de dois digitos e o motivo grafico do portal */
${s('num')}{font-family:var(--fd);font-weight:700;font-size:13px;line-height:1;letter-spacing:.02em;color:var(--bdac);flex:none;font-variant-numeric:tabular-nums}
${s('kick')}{display:inline-flex;align-items:center;gap:9px;font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:var(--kls);color:var(--bdac)}
${s('kick')} span{color:var(--bdfraco);font-weight:500;letter-spacing:.08em}
${s('kick')} a{color:inherit;text-decoration:none}
${s('sec')}{display:flex;align-items:baseline;justify-content:space-between;gap:10px 20px;flex-wrap:wrap;margin:0 0 20px;padding:0 0 10px;border-bottom:2px solid var(--bdink)}
${s('sec')} h1,${s('sec')} h2{font-family:var(--fd);font-weight:700;font-size:clamp(19px,2vw,24px);line-height:1.2;letter-spacing:-.016em;color:var(--bdink);margin:0;text-align:left}
${s('sec')} .more{font-family:var(--fb);font-size:12.5px;font-weight:600;color:var(--bdfraco);text-decoration:none}
${s('sec')} .more:hover{color:var(--bdac)}
${s('bloco')}{margin:0 0 48px}

/* ---------- abertura partida: texto a esquerda, foto a direita ---------- */
${s('abre')}{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:0 38px;align-items:center;margin:30px 0 42px;padding:0 0 34px;border-bottom:1px solid var(--bdfio);text-decoration:none;color:inherit}
${s('abre')} .tx{display:flex;flex-direction:column;gap:14px;text-align:left;order:1}
${s('abre')} .im{display:block;overflow:hidden;background:var(--ph);aspect-ratio:var(--hero-ar,4/3);border-radius:var(--rad-lg,4px);order:2}
${s('abre')} .im img{width:100%;height:100%;object-fit:cover;display:block}
${s('abre')} .h{font-family:var(--fd);font-weight:700;font-size:clamp(26px,3.1vw,39px);line-height:1.12;letter-spacing:-.023em;color:var(--bdink);margin:0;text-align:left}
${s('abre')}:hover .h{color:var(--bdac)}
${s('abre')} .d{font-family:var(--fb);font-size:16.5px;font-weight:400;line-height:1.7;color:var(--bdfraco);margin:0;text-align:left;max-width:52ch}

/* ---------- a grade de fichas deitadas ---------- */
${s('grade')}{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 var(--bdgap)}
${s('ficha')}{display:grid;grid-template-columns:104px minmax(0,1fr);gap:0 16px;align-items:start;padding:20px 0;border-top:1px solid var(--bdfio2);text-decoration:none;color:inherit}
${s('ficha')}:hover .h{color:var(--bdac)}
${s('ficha')} .im{display:block;width:100%;aspect-ratio:1/1;overflow:hidden;background:var(--ph);border-radius:var(--rad-sm,3px)}
${s('ficha')} .im img{width:100%;height:100%;object-fit:cover;display:block}
${s('ficha')} .tx{display:flex;flex-direction:column;gap:7px;text-align:left;min-width:0}
${s('ficha')} .lin{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
${s('ficha')} .h{font-family:var(--fd);font-weight:600;font-size:17px;line-height:1.29;letter-spacing:-.011em;color:var(--bdink);margin:0;text-align:left}
${s('ficha')} .d{font-family:var(--fb);font-size:13.5px;font-weight:400;line-height:1.62;color:var(--bdfraco);margin:0;text-align:left}
/* a ficha sem foto ocupa a calha da miniatura com o indice, e nao fica torta */
${s('semfoto')} .vaga{display:flex;align-items:flex-start;justify-content:flex-start;padding-top:2px}
${s('semfoto')} .vaga span{font-family:var(--fd);font-weight:700;font-size:34px;line-height:1;color:var(--bdfio);font-variant-numeric:tabular-nums}

/* ---------- artigo: coluna unica larga ---------- */
${s('peca')}{max-width:74ch;margin:26px auto 0}
${s('peca')} h1{font-family:var(--fd);font-weight:700;font-size:clamp(28px,3.4vw,42px);line-height:1.12;letter-spacing:-.024em;color:var(--bdink);margin:8px 0 14px;text-align:left}
${s('dek')}{display:block;font-family:var(--fb);font-size:18.5px;font-weight:400;line-height:1.64;color:var(--bdfraco);margin:0 0 22px;text-align:left}
${s('apoio')}{display:flex;align-items:center;gap:14px 18px;flex-wrap:wrap;padding:0 0 20px;margin:0 0 26px;border-bottom:1px solid var(--bdfio)}
${s('pena')}{display:flex;align-items:center;gap:11px;text-decoration:none;color:inherit}
${s('pena')} img{width:42px;height:42px;object-fit:cover;background:var(--ph);flex:none;border-radius:50%}
${s('pena')} b{display:block;font-family:var(--fd);font-weight:700;font-size:14.5px;line-height:1.24;color:var(--bdink)}
${s('pena')}:hover b{color:var(--bdac)}
${s('pena')} i{display:block;font-style:normal;font-family:var(--fb);font-size:11px;font-weight:500;letter-spacing:.09em;color:var(--bdfraco);margin-top:3px}
${s('data')}{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.06em;color:var(--bdfraco);margin-left:auto}
${s('gravura')}{margin:0 0 28px}
/* 🔴 height:auto NAO e enfeite, e nenhuma crase pode entrar neste comentario.
   A tag ja traz width e height, mas o navegador so usa esse par para reservar
   a altura quando o CSS deixa a altura livre. Com width:100% sozinho a reserva
   nao acontece, a pagina pula quando a foto chega, e o CLS desta pagina era
   0,128. A crase fecharia o template literal e derrubaria o archs.js. */
${s('gravura')} img{width:100%;height:auto;display:block;border-radius:var(--rad-lg,4px)}
${s('gravura')} figcaption{font-family:var(--fb);font-size:12.5px;line-height:1.62;color:var(--bdfraco);padding:9px 0 0;text-align:left}

/* o contador dos subtitulos e a volta do indice de dois digitos da capa */
${s('texto')}{font-family:var(--fb);font-size:17.5px;line-height:1.78;color:var(--bdink);counter-reset:bdsec}
${s('texto')} p{margin:0 0 1.25em;text-align:left}
${s('texto')} h2{counter-increment:bdsec;font-family:var(--fd);font-weight:700;font-size:25px;line-height:1.24;letter-spacing:-.017em;color:var(--bdink);margin:2.1em 0 .6em;scroll-margin-top:20px;text-align:left}
${s('texto')} h2::before{content:counter(bdsec,decimal-leading-zero);display:block;font-size:13px;line-height:1;letter-spacing:.02em;color:var(--bdac);margin:0 0 9px;font-variant-numeric:tabular-nums}
${s('texto')} h3{font-family:var(--fd);font-weight:600;font-size:19.5px;line-height:1.32;color:var(--bdink);margin:1.7em 0 .5em;scroll-margin-top:20px;text-align:left}
${s('texto')} a{color:var(--bdac);text-decoration:underline;text-underline-offset:3px}
${s('texto')} ul,${s('texto')} ol{margin:0 0 1.25em;padding-left:1.35em;text-align:left}
${s('texto')} li{margin-bottom:.5em}
/* a imagem do corpo vem de acervo de WordPress, com miniatura de 300, 400 e
   450 pixels misturada com foto de 1024. Sem regra, cada uma aparece no tamanho
   nativo e a coluna vira uma pilha de retangulos de tamanhos diferentes. A
   larga ocupa a coluna inteira; a estreita fica como esta, porque esticar ate
   os 700 da coluna borra. O corte entre as duas e feito no conteudo, que e o
   unico lugar que conhece a medida do arquivo */
${s('texto')} img{display:block;height:auto;margin:0;border-radius:var(--rad-sm,3px)}
/* 🔴 o alvo e ATRIBUTO, e nao classe: o motor troca todo nome de classe da
   pagina por um hash, e classe literal gravada no corpo do artigo nao passa
   por essa troca. A regra nunca casaria e a imagem subiria sem estilo */
${s('texto')} img[data-fig="larga"]{width:100%;max-width:100%}
/* a que nao e deitada para em 460px: foto quadrada ocupando a coluna inteira
   vira um bloco de 700px de altura no meio do texto */
${s('texto')} img[data-fig="estreita"]{width:100%;max-width:min(100%,460px)}
${s('texto')} figure{margin:1.9em 0}
${s('texto')} figure img{margin:0}
${s('texto')} figure figcaption{font-family:var(--fb);font-size:12.5px;line-height:1.6;color:var(--bdfraco);padding:8px 0 0;text-align:left}
${s('texto')} p > img{margin:1.9em 0}
${s('texto')} blockquote{margin:1.8em 0;padding:4px 0 4px 20px;border-left:3px solid var(--bdac);font-family:var(--fd);font-size:20px;line-height:1.5;color:var(--bdink);text-align:left}
${s('texto')} blockquote p{margin:0;font:inherit;text-align:left}
${s('escoa')}{display:block;overflow-x:auto;-webkit-overflow-scrolling:touch;margin:1.7em 0}
${s('texto')} table{width:100%;border-collapse:collapse;font-family:var(--fb);font-size:14.5px;min-width:440px}
${s('texto')} caption{font-family:var(--fb);font-size:12.5px;color:var(--bdfraco);text-align:left;padding:0 0 9px}
${s('texto')} th,${s('texto')} td{border:0;border-bottom:1px solid var(--bdfio2);background:transparent;padding:11px 14px 11px 0;text-align:left;vertical-align:top}
${s('texto')} thead th{border-bottom:2px solid var(--bdink);font-weight:700;font-size:12px;letter-spacing:.07em;color:var(--bdink)}

/* ---------- relacionados ---------- */
${s('depois')}{max-width:74ch;margin:44px auto 0;padding:26px 0 0;border-top:2px solid var(--bdink)}
${s('depois')} h2{font-family:var(--fd);font-weight:700;font-size:19px;line-height:1.2;color:var(--bdink);margin:0 0 6px;text-align:left}
${s('lista')}{display:flex;flex-direction:column}
${s('item')}{display:flex;align-items:baseline;gap:12px;padding:14px 0;border-bottom:1px solid var(--bdfio2);text-decoration:none;color:inherit}
${s('item')} .h{font-family:var(--fd);font-weight:600;font-size:16px;line-height:1.32;color:var(--bdink);text-align:left}
${s('item')}:hover .h{color:var(--bdac)}

/* ---------- rodape ---------- */
${s('rodape')}{margin-top:60px;border-top:3px solid var(--bdink);background:var(--bdlavado)}
${s('rodapein')}{max-width:var(--maxw);margin:0 auto;padding:38px var(--bdpad) 26px;box-sizing:border-box}
${s('rgrid')}{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:26px 30px}
${s('rgrid')} h2{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.15em;color:var(--bdfraco);margin:0 0 12px;text-align:left}
/* 🔴 o :not e obrigatorio, e nenhuma crase pode entrar neste comentario.
   Sem o :not, esta regra tambem pega o proprio logotipo, que e um link
   dentro da mesma grade: o display:block ganha do inline-flex da marca e o
   simbolo cai para cima do nome, em duas linhas, so no rodape.
   A crase fecharia o template literal e derrubaria o archs.js inteiro. */
${s('rgrid')} a:not(${s('marca')}){display:block;font-family:var(--fb);font-size:14px;color:var(--bdink);text-decoration:none;padding:5px 0;text-align:left}
${s('rgrid')} a:not(${s('marca')}):hover{color:var(--bdac)}
${s('rsobre')}{font-family:var(--fb);font-size:14px;line-height:1.68;color:var(--bdfraco);margin:12px 0 0;max-width:42ch;text-align:left}
${s('rbase')}{font-family:var(--fb);font-size:12.5px;color:var(--bdfraco);margin-top:28px;padding-top:18px;border-top:1px solid var(--bdfio);text-align:left}
${s('crumbs')}{font-family:var(--fb);font-size:12.5px;color:var(--bdfraco);margin:20px 0 0}
${s('crumbs')} a{color:var(--bdfraco);text-decoration:none}
${s('crumbs')} a:hover{color:var(--bdac)}
${s('crumbs')} .sep{margin:0 6px;color:var(--bdfio)}
${s('crumbs')} .cur{color:var(--bdink)}

@media(max-width:900px){
${s('abre')}{grid-template-columns:minmax(0,1fr);gap:20px}
${s('abre')} .tx{order:2}
${s('abre')} .im{order:1}
${s('grade')}{grid-template-columns:minmax(0,1fr);gap:0}
${s('rgrid')}{grid-template-columns:1fr 1fr}
}
@media(max-width:640px){
${s('linha1')}{flex-wrap:wrap}
${s('ficha')}{grid-template-columns:78px minmax(0,1fr);gap:0 13px}
${s('peca')},${s('depois')}{max-width:none}
${s('data')}{margin-left:0}
${s('rgrid')}{grid-template-columns:1fr}
/* a tabela vira ficha: sem isto ela sai da tela e o gesto de arrastar nao e
   descoberto. O thead sai da tela mas continua no DOM, para o leitor de tela */
${s('escoa')}{overflow:visible}
${s('texto')} table{min-width:0}
${s('texto')} caption{display:none}
${s('texto')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
${s('texto')} table,${s('texto')} tbody,${s('texto')} tr,${s('texto')} th,${s('texto')} td{display:block;width:auto}
${s('texto')} tbody tr{border:1px solid var(--bdfio);border-radius:12px;padding:2px 18px 16px;margin-bottom:13px;background:var(--bdpaper)}
${s('texto')} tbody th,${s('texto')} tbody td{border:0;background:transparent}
${s('texto')} tbody th{border-bottom:1px solid var(--bdfio);padding:14px 0 12px;font-size:16px}
${s('texto')} tbody td{padding:14px 0 0;text-align:left;line-height:1.55}
${s('texto')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--bdfraco);margin-bottom:3px}
}
`;
}

/* O logotipo e o SIMBOLO mais o nome, e o simbolo sai do mesmo `site.iconSvg`
   que gera o favicon. Fonte unica: o que esta na aba do navegador e o que esta
   no cabecalho sao literalmente o mesmo desenho, e nao dois parecidos.

   A ultima palavra do nome fica na cor da marca e o resto na tinta do texto. E
   o mesmo par de tons das duas metades da capsula, entao o logotipo repete a
   ideia do simbolo em vez de so ficar do lado dele. */
function bdLogo(ctx, cls) {
  const { c, H } = ctx;
  const nome = String(ctx.site.shortName || ctx.site.name).trim();
  const i = nome.lastIndexOf(' ');
  const cabeca = i > 0 ? H.esc(nome.slice(0, i)) + ' ' : '';
  const fim = H.esc(i > 0 ? nome.slice(i + 1) : nome);
  const bruto = String(ctx.site.iconSvg || '');
  const sim = bruto
    ? '<span class="' + c('sim') + '" aria-hidden="true">'
      + bruto.replace(/\swidth="[^"]*"/, ' width="44"')
             .replace(/\sheight="[^"]*"/, ' height="44"')
             .replace(/\srole="[^"]*"/, '')
             .replace(/\saria-label="[^"]*"/, '')
      + '</span>'
    : '';
  const tag = ctx.site.tagline ? `<i>${H.esc(ctx.site.tagline)}</i>` : '';
  return `<a class="${c(cls)}" href="/">${sim}`
    + `<span class="${c('nom')}"><b>${cabeca}<em>${fim}</em></b>${tag}</span></a>`;
}

function bdHeader(ctx, menu) {
  const { c, H } = ctx;
  const links = (menu || []).map(m => `<a href="${H.curl(m.slug)}">${H.esc(m.name)}</a>`).join('');
  return `<body>
<header class="${c('topo')}"><div class="${c('topoin')}">
<div class="${c('linha1')}">${bdLogo(ctx, 'marca')}</div>
<nav class="${c('nav')}" aria-label="Editorias">${links}</nav>
</div></header>
<main class="${c('folha')}">`;
}

function bdFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const eds = (menu || []).map(m => `<a href="${H.curl(m.slug)}">${H.esc(m.name)}</a>`).join('');
  return `</main>
<footer class="${c('rodape')}"><div class="${c('rodapein')}">
<div class="${c('rgrid')}">
<div>${bdLogo(ctx, 'marca')}<p class="${c('rsobre')}">${H.esc(site.description || site.tagline || '')}</p></div>
<div><h2>Editorias</h2>${eds}</div>
<div><h2>Institucional</h2>${H.instLinks()}</div>
<div><h2>Redação</h2>
<a href="/contato/">Falar com a redação</a>
<a href="/contato/">Sugerir uma pauta de saúde</a>
<a href="/contato/">Corrigir uma informação</a>
<a href="/busca/">Buscar no acervo</a></div>
</div>
<div class="${c('rbase')}">&copy; ${H.year()} ${H.esc(site.name)}. Conteúdo informativo, não substitui consulta médica. ${H.esc(site.domain)}</div>
</div></footer>
${H.bodyEnd()}`;
}

/* A legenda so vale quando diz algo que o titulo nao disse. Metade do acervo
   importado traz o alt como copia do titulo ou do slug, e imprimir isso poe a
   mesma frase duas vezes na tela. */
function bdLegenda(ctx, art) {
  const alt = art.image && art.image.alt ? String(art.image.alt).trim() : '';
  const t = String(art.title || '');
  const chato = (x) => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const cSlug = chato(art.slug), cAlt = chato(alt);
  const pref = cAlt.length >= 25 && (cSlug.indexOf(cAlt) === 0 || cAlt.indexOf(cSlug) === 0);
  if (!alt || cAlt === chato(t) || cAlt === cSlug || pref) return '';
  return alt;
}

/* A linha fina so entra se nao repetir a abertura do corpo. */
function bdDekVale(art) {
  if (!art) return '';
  const d = String(art.dek || '').trim();
  if (!d) return '';
  const chato = (x) => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const corpo = chato(String(art.content || '').replace(/<[^>]+>/g, ' ')).slice(0, 600);
  const cd = chato(d);
  if (cd.length >= 30 && corpo.indexOf(cd.slice(0, 60)) >= 0) return '';
  return d;
}

/* A ficha e a unidade da pagina: indice, editoria, titulo e resumo. Sem foto ela
   continua ficha, com o indice ocupando a calha da miniatura. */
function bdFicha(ctx, a, i) {
  const { c, H } = ctx;
  const d = bdDekVale(a) || a.excerpt || '';
  const n = String(i + 1).padStart(2, '0');
  const tx = `<span class="tx">`
    + `<span class="lin"><span class="${c('num')}">${n}</span>`
    + `<span class="${c('kick')}">${H.cat(a)}<span>${H.esc(H.dateShort(a.date))}</span></span></span>`
    + `<span class="h">${H.esc(a.title)}</span>`
    + `${d ? `<span class="d">${H.esc(H.corta(d, 96))}</span>` : ''}`
    + `</span>`;
  if (a.image) {
    return `<a class="${c('ficha')}" href="${H.url(a)}"><span class="im">${H.pic(a, false)}</span>${tx}</a>`;
  }
  return `<a class="${c('ficha')} ${c('semfoto')}" href="${H.url(a)}">`
    + `<span class="vaga"><span>${n}</span></span>${tx}</a>`;
}

function bdSecHead(ctx, nome, cs) {
  const { c, H } = ctx;
  return `<div class="${c('sec')}"><h2>${H.esc(nome)}</h2>`
    + `${cs ? `<a class="more" href="${H.curl(cs)}">Tudo em ${H.esc(nome)}</a>` : ''}</div>`;
}

function bdHome(ctx, arts, menu) {
  const { c, H } = ctx;
  const pref = ctx.site.heroFrom;
  const lista = arts.slice();
  let top = lista[0];
  if (pref) {
    const i = lista.findIndex(a => a.category && a.category.slug === pref);
    if (i > 0) top = lista[i];
  }
  const resto = lista.filter(a => a !== top);
  const dTop = bdDekVale(top) || (top && top.excerpt) || '';
  const abre = top
    ? `<a class="${c('abre')}" href="${H.url(top)}">`
      + `<span class="tx"><span class="${c('kick')}">${H.cat(top)}<span>${H.esc(H.dateShort(top.date))}</span></span>`
      + `<span class="h">${H.esc(top.title)}</span>`
      + `${dTop ? `<span class="d">${H.esc(H.corta(dTop, 180))}</span>` : ''}</span>`
      + `${top.image ? `<span class="im">${H.pic(top, true)}</span>` : ''}`
      + `</a>`
    : '';

  const usados = new Set(top ? [top.slug] : []);
  const primeiros = resto.slice(0, 8);
  primeiros.forEach(a => usados.add(a.slug));
  const grade = `<div class="${c('grade')}">`
    + primeiros.map((a, i) => bdFicha(ctx, a, i)).join('') + `</div>`;

  const fixas = Array.isArray(ctx.site.homeSections) ? ctx.site.homeSections : null;
  const porCat = new Map();
  for (const a of resto.slice(8)) {
    if (!a.category) continue;
    const k = a.category.slug;
    if (!porCat.has(k)) porCat.set(k, { nome: a.category.name, itens: [] });
    porCat.get(k).itens.push(a);
  }
  const ordem = fixas
    ? fixas.filter(k => porCat.has(k))
    : Array.from(porCat.keys()).sort((a, b) => porCat.get(b).itens.length - porCat.get(a).itens.length);
  const blocos = ordem.slice(0, 5).map(k => {
    const g = porCat.get(k);
    const itens = g.itens.filter(a => !usados.has(a.slug)).slice(0, 6);
    if (!itens.length) return '';
    itens.forEach(a => usados.add(a.slug));
    return `<section class="${c('bloco')}">${bdSecHead(ctx, g.nome, k)}`
      + `<div class="${c('grade')}">${itens.map((a, i) => bdFicha(ctx, a, i)).join('')}</div></section>`;
  }).join('\n');

  return `${H.head(ctx, H.homeMeta(ctx.site))}
${bdHeader(ctx, menu)}
${H.h1(ctx)}
${abre}
${grade}
${blocos}
${bdFooter(ctx, menu)}`;
}

function bdArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;

  const corpo = String(art.content).replace(/<table\b/gi, '<table role="table"');

  const eq = (ctx.site.equipe || []).find(x => x.nome === art.author);
  const pena = eq
    ? `<a class="${c('pena')}" rel="author" href="/autor/${H.esc(eq.slug)}/"><img src="/img/autores/${H.esc(eq.slug)}.webp" width="42" height="42" alt="" aria-hidden="true" loading="lazy"><span><b>${H.esc(eq.nome)}</b><i>${P.readMin} min de leitura</i></span></a>`
    : `<span class="${c('pena')}"><span><b>${H.esc(art.author || ctx.site.name)}</b><i>${P.readMin} min de leitura</i></span></span>`;

  const leg = bdLegenda(ctx, art);
  const figura = art.image
    ? `<figure class="${c('gravura')}">${H.pic(art, true)}${leg ? `<figcaption>${H.esc(leg)}</figcaption>` : ''}</figure>`
    : '';
  const dek = bdDekVale(art);

  const depois = (related || []).length
    ? `<section class="${c('depois')}"><h2>Veja também em ${H.esc(P.catName)}</h2>`
      + `<div class="${c('lista')}">`
      + related.slice(0, 5).map((a, i) => `<a class="${c('item')}" href="${H.url(a)}">`
        + `<span class="${c('num')}">${String(i + 1).padStart(2, '0')}</span>`
        + `<span class="h">${H.esc(a.title)}</span></a>`).join('')
      + `</div></section>`
    : '';

  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${bdHeader(ctx, menu)}
${H.progressBar(ctx)}
${H.crumbs(ctx, art, P)}
<article class="${c('peca')}">
<span class="${c('kick')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${dek ? `<span class="${c('dek')}">${H.esc(dek)}</span>` : ''}
<div class="${c('apoio')}">${pena}<span class="${c('data')}">${H.esc(P.dstr)}</span></div>
${figura}
<div class="${c('texto')}">${corpo}</div>
${H.share(ctx, P)}
</article>
${depois}
${bdFooter(ctx, menu)}
${H.progressScript(ctx)}`;
}

/* A listagem precisa de h1 proprio: sem ele a pagina de editoria sobe sem
   titulo de nivel 1, e o cartao vira o primeiro heading da pagina. */
function bdList(ctx, opts) {
  const { c, H } = ctx;
  const itens = opts.items || [];
  return `${H.head(ctx, H.listMeta(ctx, opts))}
${bdHeader(ctx, opts.menu)}
<div class="${c('sec')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('rsobre')}">${H.esc(opts.desc)}</p>` : ''}
<div class="${c('grade')}">${itens.map((a, i) => bdFicha(ctx, a, i)).join('')}</div>
${bdFooter(ctx, opts.menu)}`;
}

